window.EscDados.registrarFlashcards("flashcards-assuntos-novos", [
  {"id": "fc-n-001", "assuntoId": "ass-neuro-avc", "frente": "Até quanto tempo do início dos sintomas cabe a trombólise venosa no AVC isquêmico, e qual pressão é exigida antes dela?", "verso": "Até 4,5 horas do início (ou da última vez em que o paciente foi visto bem). A pressão precisa estar abaixo de 185/110 mmHg antes da infusão e abaixo de 180/105 mmHg nas 24 horas seguintes.", "fonte": "AHA/ASA, diretriz de AVC isquêmico agudo, 2019", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-002", "assuntoId": "ass-neuro-avc", "frente": "Qual é o primeiro exame de imagem na suspeita de AVC agudo, e para quê?", "verso": "Tomografia de crânio sem contraste, feita o mais rápido possível: o objetivo principal é excluir hemorragia antes de decidir pela trombólise. No AVC isquêmico das primeiras horas ela costuma ser normal.", "fonte": "AHA/ASA, diretriz de AVC isquêmico agudo, 2019", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-003", "assuntoId": "ass-neuro-avc", "frente": "Quem é candidato a trombectomia mecânica no AVC isquêmico?", "verso": "Oclusão de grande vaso da circulação anterior (carótida interna, segmento M1 da cerebral média) com déficit relevante: até 6 horas do início, e até 24 horas em casos selecionados por imagem que mostra tecido ainda recuperável.", "fonte": "AHA/ASA 2019; estudos DAWN e DEFUSE-3", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-004", "assuntoId": "ass-neuro-cefaleias", "frente": "Quais sinais de alarme numa cefaleia pedem investigação com imagem?", "verso": "Início súbito e explosivo (\"a pior da vida\"), primeira cefaleia após os 50 anos, déficit neurológico focal, febre ou rigidez de nuca, piora progressiva, papiledema, imunossupressão ou câncer, e mudança do padrão de uma cefaleia antiga.", "fonte": "ICHD-3, 2018; mnemônico SNOOP", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-005", "assuntoId": "ass-neuro-cefaleias", "frente": "Qual é o tratamento específico da crise de enxaqueca moderada a intensa, e quando ele é contraindicado?", "verso": "Triptano (por exemplo, sumatriptana), que pode ser associado a um anti-inflamatório. Por ser vasoconstritor, é contraindicado em doença coronariana, AVC prévio, doença arterial periférica e hipertensão não controlada.", "fonte": "Consenso da Sociedade Brasileira de Cefaleia; ICHD-3, 2018", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-006", "assuntoId": "ass-neuro-cefaleias", "frente": "Como é a cefaleia em salvas e como se trata a crise?", "verso": "Dor orbitária unilateral muito intensa, de 15 a 180 minutos, com sinais autonômicos do mesmo lado (lacrimejamento, rinorreia, ptose, miose), em salvas de semanas, mais em homens. A crise responde a oxigênio a 100% em alto fluxo ou sumatriptana subcutânea.", "fonte": "ICHD-3, 2018", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-007", "assuntoId": "ass-neuro-epilepsia", "frente": "Quando uma crise convulsiva vira estado de mal epiléptico, e qual é a primeira droga?", "verso": "Crise contínua por 5 minutos ou mais, ou crises repetidas sem recuperação da consciência entre elas. Primeira linha: benzodiazepínico (diazepam ou midazolam venoso; midazolam intramuscular se não houver acesso).", "fonte": "ILAE 2015; American Epilepsy Society, 2016", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-008", "assuntoId": "ass-neuro-epilepsia", "frente": "Quais são as opções de segunda linha no estado de mal epiléptico, depois do benzodiazepínico?", "verso": "Fenitoína (ou fosfenitoína), valproato ou levetiracetam por via venosa — têm eficácia semelhante. Se as crises persistirem, é estado de mal refratário: intubação e anestésico contínuo (midazolam, propofol), com monitorização.", "fonte": "American Epilepsy Society, 2016; estudo ESETT, 2019", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-009", "assuntoId": "ass-neuro-epilepsia", "frente": "Qual anticonvulsivante deve ser evitado em mulheres que podem engravidar, e por quê?", "verso": "Valproato: é o mais teratogênico (defeitos do tubo neural, malformações e prejuízo do desenvolvimento neurocognitivo). Toda mulher com epilepsia em idade fértil deve usar ácido fólico.", "fonte": "ILAE/EAN, recomendações sobre valproato, 2018", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-010", "assuntoId": "ass-neuro-neuromuscular", "frente": "Como se apresenta e como se trata a síndrome de Guillain-Barré?", "verso": "Fraqueza flácida ascendente e simétrica com arreflexia, muitas vezes semanas após uma infecção (Campylobacter). O líquor mostra dissociação proteíno-citológica. Trata-se com imunoglobulina venosa ou plasmaférese, vigiando a capacidade vital pelo risco de insuficiência respiratória.", "fonte": "Guia EAN/PNS de Guillain-Barré, 2023", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-011", "assuntoId": "ass-neuro-neuromuscular", "frente": "Qual é o quadro típico da miastenia gravis e o exame de imagem obrigatório?", "verso": "Fraqueza que flutua e piora com o esforço, com ptose e diplopia, anticorpo antirreceptor de acetilcolina. O sintoma melhora com piridostigmina. Todo paciente faz tomografia de tórax em busca de timoma.", "fonte": "Consenso internacional de miastenia gravis, 2020", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-012", "assuntoId": "ass-neuro-neuromuscular", "frente": "O que caracteriza a esclerose lateral amiotrófica ao exame?", "verso": "Sinais de primeiro neurônio motor (hiper-reflexia, Babinski, espasticidade) junto com sinais de segundo neurônio (fasciculações, atrofia, fraqueza), sem alteração de sensibilidade. O riluzol prolonga discretamente a sobrevida.", "fonte": "Critérios de El Escorial revisados / Gold Coast, 2020", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-013", "assuntoId": "ass-neuro-movimento", "frente": "Quais são os critérios clínicos centrais da doença de Parkinson?", "verso": "Bradicinesia obrigatória, associada a tremor de repouso e/ou rigidez, geralmente assimétricos no início. Boa resposta à levodopa apoia o diagnóstico.", "fonte": "Critérios da Movement Disorder Society, 2015", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-014", "assuntoId": "ass-neuro-movimento", "frente": "Como diferenciar tremor essencial do tremor da doença de Parkinson?", "verso": "O essencial é postural e de ação (piora ao segurar um copo), bilateral, costuma ter história familiar e melhora com álcool; trata-se com propranolol ou primidona. O parkinsoniano é de repouso e melhora com o movimento.", "fonte": "Consenso da Movement Disorder Society sobre tremor, 2018", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-015", "assuntoId": "ass-neuro-movimento", "frente": "Que medicamentos causam parkinsonismo e devem ser investigados antes do diagnóstico de Parkinson?", "verso": "Antipsicóticos (sobretudo os típicos, como haloperidol), metoclopramida, flunarizina e cinarizina. O parkinsonismo por droga tende a ser simétrico e melhora semanas a meses após a suspensão.", "fonte": "Movement Disorder Society, 2015", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-016", "assuntoId": "ass-neuro-vertigem", "frente": "Que achados do exame HINTS sugerem que uma vertigem aguda é central (AVC), e não periférica?", "verso": "Teste do impulso cefálico NORMAL, nistagmo que muda de direção com o olhar (ou vertical) e desvio vertical dos olhos no teste de cobertura (skew). Qualquer um deles em síndrome vestibular aguda pede investigação de AVC de fossa posterior.", "fonte": "Kattah et al., Stroke 2009; diretrizes de tontura aguda", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-017", "assuntoId": "ass-neuro-vertigem", "frente": "Como se diagnostica e se trata a vertigem posicional paroxística benigna?", "verso": "Vertigem de segundos desencadeada por mudança de posição da cabeça. Diagnóstico pela manobra de Dix-Hallpike (nistagmo com latência e fatigável); tratamento com manobra de reposicionamento (Epley), não com medicamento.", "fonte": "AAO-HNS, diretriz de VPPB, 2017", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-018", "assuntoId": "ass-neuro-vertigem", "frente": "Qual é a diferença entre neurite vestibular e labirintite?", "verso": "As duas causam vertigem aguda contínua por dias, geralmente após quadro viral. Na neurite a audição está preservada; na labirintite há perda auditiva associada.", "fonte": "Revisão de síndrome vestibular aguda, diretrizes da Bárány Society", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-019", "assuntoId": "ass-neuro-desmielinizante", "frente": "Qual é o perfil típico da esclerose múltipla e o que o diagnóstico exige?", "verso": "Mulher jovem com surtos de déficit neurológico em locais diferentes do sistema nervoso central (neurite óptica, mielite, tronco). O diagnóstico exige disseminação no tempo e no espaço, demonstrada pela clínica e pela ressonância (lesões periventriculares, justacorticais, infratentoriais, medulares).", "fonte": "Critérios de McDonald, 2017", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-020", "assuntoId": "ass-neuro-desmielinizante", "frente": "Como se trata o surto de esclerose múltipla?", "verso": "Metilprednisolona venosa em altas doses por 3 a 5 dias: acelera a recuperação do surto, mas não muda a evolução da doença — isso é papel das terapias modificadoras de doença.", "fonte": "Consenso brasileiro de esclerose múltipla (ABN/BCTRIMS), 2018", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-021", "assuntoId": "ass-neuro-desmielinizante", "frente": "Quais são os achados da neurite óptica?", "verso": "Perda visual unilateral em dias, dor à movimentação do olho, alteração da visão de cores e defeito pupilar aferente relativo. Pode ser a primeira manifestação da esclerose múltipla.", "fonte": "Optic Neuritis Treatment Trial; consenso ABN/BCTRIMS", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-022", "assuntoId": "ass-psiq-humor", "frente": "O que define um episódio depressivo maior?", "verso": "Pelo menos 5 sintomas por no mínimo 2 semanas, com prejuízo funcional, sendo obrigatório humor deprimido ou perda de interesse/prazer (anedonia).", "fonte": "DSM-5-TR, 2022", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-023", "assuntoId": "ass-psiq-humor", "frente": "Qual é o cuidado com o lítio no transtorno bipolar?", "verso": "A faixa terapêutica é estreita (cerca de 0,6 a 1,2 mEq/L). Intoxicação dá tremor grosseiro, ataxia, vômitos e confusão; desidratação, AINE, IECA e tiazídicos elevam o nível. Monitorar lítio, função renal e tireoide.", "fonte": "CANMAT/ISBD, diretriz de transtorno bipolar, 2018", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-024", "assuntoId": "ass-psiq-humor", "frente": "Em quanto tempo o antidepressivo faz efeito e por quanto tempo se mantém no primeiro episódio?", "verso": "A resposta começa a aparecer em 2 a 4 semanas. Após a remissão do primeiro episódio, mantém-se a mesma dose por pelo menos 6 a 12 meses antes de pensar em retirada gradual.", "fonte": "CANMAT, diretriz de depressão, 2023", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-025", "assuntoId": "ass-psiq-psicoses", "frente": "Qual é o critério de tempo para o diagnóstico de esquizofrenia?", "verso": "Sinais da doença por pelo menos 6 meses, incluindo ao menos 1 mês de sintomas ativos (delírios, alucinações, discurso desorganizado). Menos de 6 meses é transtorno esquizofreniforme; menos de 1 mês, transtorno psicótico breve.", "fonte": "DSM-5-TR, 2022", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-026", "assuntoId": "ass-psiq-psicoses", "frente": "Quando se indica clozapina e qual é o risco que exige vigilância?", "verso": "Na esquizofrenia resistente, depois de falha de pelo menos dois antipsicóticos em dose e tempo adequados. Pode causar agranulocitose, por isso exige hemograma periódico.", "fonte": "Diretrizes da APA para esquizofrenia, 2020", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-027", "assuntoId": "ass-psiq-psicoses", "frente": "Como se reconhece a síndrome neuroléptica maligna?", "verso": "Febre, rigidez muscular em cano de chumbo, alteração do nível de consciência e instabilidade autonômica, com CPK elevada, após antipsicótico. Conduta: suspender o antipsicótico, suporte intensivo; dantroleno ou bromocriptina nos casos graves.", "fonte": "Revisões de síndrome neuroléptica maligna; APA 2020", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-028", "assuntoId": "ass-psiq-substancias", "frente": "Em que tempo aparecem as manifestações da abstinência alcoólica, e qual é o tratamento?", "verso": "Tremor, sudorese e taquicardia em 6 a 24 horas; convulsões entre 12 e 48 horas; delirium tremens entre 48 e 96 horas. O tratamento é benzodiazepínico (diazepam; lorazepam se houver hepatopatia grave).", "fonte": "ASAM, diretriz de abstinência alcoólica, 2020", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-029", "assuntoId": "ass-psiq-substancias", "frente": "Por que se dá tiamina antes de glicose no paciente alcoolista?", "verso": "Para prevenir a encefalopatia de Wernicke (confusão, ataxia e oftalmoplegia): a oferta de glicose consome a tiamina que já está em falta e pode precipitar o quadro.", "fonte": "Diretrizes da EFNS para encefalopatia de Wernicke, 2010", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-030", "assuntoId": "ass-psiq-substancias", "frente": "Qual é a tríade da intoxicação por opioide e o antídoto?", "verso": "Miose, depressão respiratória e rebaixamento do nível de consciência. O antídoto é a naloxona, que tem meia-vida curta: o paciente pode voltar a deprimir e precisa ficar em observação.", "fonte": "Protocolos de toxicologia clínica; OMS, manejo de overdose de opioides, 2014", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-031", "assuntoId": "ass-psiq-infantil", "frente": "O que é preciso para o diagnóstico de TDAH e qual é o tratamento de primeira linha no escolar?", "verso": "Sintomas de desatenção e/ou hiperatividade-impulsividade antes dos 12 anos, por pelo menos 6 meses, em dois ou mais ambientes (casa e escola). No escolar, metilfenidato associado a intervenção comportamental e escolar.", "fonte": "DSM-5-TR; AAP, diretriz de TDAH, 2019", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-032", "assuntoId": "ass-psiq-infantil", "frente": "Quais são os sinais de alerta de transtorno do espectro autista e quando se faz a triagem?", "verso": "Pouco contato visual, não atender pelo nome, não apontar nem compartilhar atenção, fala ausente ou regressão. A triagem com M-CHAT-R é feita entre 16 e 30 meses, e o sinal de alerta leva a encaminhamento sem esperar.", "fonte": "SBP, Manual de orientação sobre TEA, 2019", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-033", "assuntoId": "ass-psiq-infantil", "frente": "Diante de uma criança com atraso de fala, qual é o primeiro exame?", "verso": "Avaliação auditiva (audiometria ou potencial evocado auditivo): a deficiência auditiva é causa tratável e precisa ser excluída antes de outros diagnósticos.", "fonte": "SBP; AAP, triagem auditiva", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-034", "assuntoId": "ass-derm-tumores", "frente": "Qual é o câncer de pele mais comum e como ele se apresenta?", "verso": "Carcinoma basocelular: pápula perolada com telangiectasias, de crescimento lento, em áreas expostas ao sol. Invade localmente, mas raramente dá metástase. Tratamento cirúrgico.", "fonte": "INCA; Sociedade Brasileira de Dermatologia", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-035", "assuntoId": "ass-derm-tumores", "frente": "De onde pode surgir o carcinoma espinocelular e onde ele é mais agressivo?", "verso": "Pode surgir de ceratose actínica e de úlceras ou cicatrizes crônicas (úlcera de Marjolin). Tem mais risco de metástase que o basocelular, sobretudo em lábio, orelha e em imunossuprimidos.", "fonte": "Sociedade Brasileira de Dermatologia; NCCN", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-036", "assuntoId": "ass-derm-tumores", "frente": "O que significa o ABCDE na avaliação de uma lesão pigmentada?", "verso": "Assimetria, Bordas irregulares, Cor variada, Diâmetro maior que 6 mm e Evolução (mudança). Lesão com esses sinais vai para biópsia excisional.", "fonte": "Sociedade Brasileira de Dermatologia", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-037", "assuntoId": "ass-derm-farmacodermias", "frente": "Como se diferenciam síndrome de Stevens-Johnson e necrólise epidérmica tóxica, e quais drogas mais causam?", "verso": "Pela área de descolamento: menos de 10% da superfície corporal é Stevens-Johnson, mais de 30% é necrólise epidérmica tóxica (entre 10% e 30%, sobreposição). Causas frequentes: alopurinol, carbamazepina, fenitoína, lamotrigina, sulfonamidas, nevirapina. Suspender a droga e tratar como grande queimado.", "fonte": "Consenso da SBD; critérios de Bastuji-Garin", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-038", "assuntoId": "ass-derm-farmacodermias", "frente": "O que é a síndrome DRESS?", "verso": "Reação a droga com febre, exantema extenso, eosinofilia, linfonodomegalia e acometimento de órgãos (principalmente fígado), surgindo de 2 a 8 semanas após o início do medicamento — o intervalo longo é o que confunde.", "fonte": "Critérios RegiSCAR", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-039", "assuntoId": "ass-derm-farmacodermias", "frente": "O que caracteriza a pustulose exantemática generalizada aguda?", "verso": "Dezenas de pequenas pústulas estéreis, não foliculares, sobre pele eritematosa, com febre, surgindo horas a poucos dias após o medicamento (beta-lactâmicos são causa comum). Resolve com a suspensão da droga.", "fonte": "Critérios EuroSCAR", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-040", "assuntoId": "ass-derm-infeccoes", "frente": "Como se reconhece e se trata a escabiose?", "verso": "Prurido pior à noite, lesões em espaços interdigitais, punhos, axilas, cintura e genitais, com outros casos na casa. Tratar o paciente e todos os contatos ao mesmo tempo (permetrina 5% ou ivermectina oral) e lavar roupas e roupa de cama.", "fonte": "Ministério da Saúde; SBD", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-041", "assuntoId": "ass-derm-infeccoes", "frente": "Qual é a diferença entre erisipela e celulite?", "verso": "A erisipela é mais superficial, com borda elevada e bem delimitada, causada principalmente por estreptococo. A celulite é mais profunda, de borda mal definida. As duas se tratam com antibiótico ativo contra estreptococo e estafilococo (cefalexina, por exemplo).", "fonte": "IDSA, infecções de pele e partes moles, 2014", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-042", "assuntoId": "ass-derm-infeccoes", "frente": "Por que a tinha do couro cabeludo não se trata só com creme?", "verso": "Porque o fungo está dentro do folículo piloso, fora do alcance do tratamento tópico. Precisa de antifúngico sistêmico (griseofulvina ou terbinafina) por semanas.", "fonte": "SBD; diretriz britânica de tinea capitis, 2014", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-043", "assuntoId": "ass-derm-autoimunes", "frente": "Quais são os sinais clássicos da psoríase e o que evitar no tratamento?", "verso": "Placas eritematodescamativas em cotovelos, joelhos e couro cabeludo, sinal de Auspitz e fenômeno de Koebner. Evita-se corticoide sistêmico: a retirada pode precipitar psoríase pustulosa ou eritrodérmica.", "fonte": "Consenso Brasileiro de Psoríase, SBD 2020", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-044", "assuntoId": "ass-derm-autoimunes", "frente": "Como diferenciar pênfigo vulgar de penfigoide bolhoso?", "verso": "Pênfigo: bolhas flácidas intraepidérmicas, Nikolsky positivo, erosões em mucosa oral, adultos de meia-idade. Penfigoide: bolhas tensas subepidérmicas, idosos, mucosa raramente acometida.", "fonte": "SBD; diretrizes europeias de doenças bolhosas", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-045", "assuntoId": "ass-derm-autoimunes", "frente": "Qual é a base do tratamento da dermatite atópica?", "verso": "Hidratação diária da pele com emolientes e evitar irritantes; nas crises, corticoide tópico. A barreira cutânea alterada é o centro da doença.", "fonte": "Consenso brasileiro de dermatite atópica (ASBAI/SBP), 2017", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-046", "assuntoId": "ass-reumato-artrites", "frente": "Qual é o quadro da artrite reumatoide e o primeiro medicamento modificador de doença?", "verso": "Poliartrite simétrica de pequenas articulações de mãos e pés com rigidez matinal de mais de 1 hora; fator reumatoide e anti-CCP (mais específico). O primeiro DMARD é o metotrexato, iniciado cedo.", "fonte": "Critérios ACR/EULAR 2010; recomendações da SBR, 2017", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-047", "assuntoId": "ass-reumato-artrites", "frente": "O que caracteriza a dor lombar inflamatória da espondilite anquilosante?", "verso": "Começa antes dos 40 anos, de forma insidiosa, melhora com exercício e não com repouso, e acorda o paciente na segunda metade da noite. Associa-se a sacroiliíte e HLA-B27; primeira linha: anti-inflamatório não esteroidal.", "fonte": "Critérios ASAS; recomendações ASAS-EULAR, 2022", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-048", "assuntoId": "ass-reumato-artrites", "frente": "O que é obrigatório antes de iniciar um anti-TNF?", "verso": "Rastrear tuberculose latente (prova tuberculínica ou IGRA e radiografia de tórax) e hepatites B e C. Infecção latente é tratada antes ou junto com o início do biológico.", "fonte": "SBR; Ministério da Saúde, manual de tuberculose, 2019", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-049", "assuntoId": "ass-reumato-les", "frente": "Quais autoanticorpos são mais sensíveis e mais específicos para lúpus?", "verso": "O FAN é o mais sensível (triagem: FAN negativo torna lúpus muito improvável). Os mais específicos são anti-DNA de dupla hélice (que acompanha a atividade e a nefrite) e anti-Sm.", "fonte": "Critérios EULAR/ACR 2019", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-050", "assuntoId": "ass-reumato-les", "frente": "Qual medicamento todo paciente com lúpus deve usar, salvo contraindicação?", "verso": "Hidroxicloroquina: reduz surtos, dano acumulado e mortalidade. Exige avaliação oftalmológica periódica pela toxicidade retiniana.", "fonte": "Recomendações EULAR para LES, 2023", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-051", "assuntoId": "ass-reumato-les", "frente": "O que caracteriza o lúpus induzido por droga?", "verso": "Surge com hidralazina, procainamida, isoniazida ou anti-TNF; tem anticorpo anti-histona, raramente acomete rim e sistema nervoso e melhora com a suspensão da droga.", "fonte": "Revisões de lúpus induzido por drogas; SBR", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-052", "assuntoId": "ass-reumato-cristais", "frente": "Como se diferenciam os cristais da gota e da pseudogota na microscopia?", "verso": "Gota: cristais de urato monossódico em agulha, com birrefringência negativa forte. Pseudogota (pirofosfato de cálcio): cristais romboides com birrefringência positiva fraca.", "fonte": "ACR/EULAR, critérios de gota 2015", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-053", "assuntoId": "ass-reumato-cristais", "frente": "Como se trata a crise de gota, e o que fazer com o alopurinol nesse momento?", "verso": "Colchicina, anti-inflamatório ou corticoide, o quanto antes. Quem já usa alopurinol NÃO suspende durante a crise. Ao iniciar o hipouricemiante, associa-se profilaxia (colchicina em dose baixa) por 3 a 6 meses.", "fonte": "ACR, diretriz de gota, 2020", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-054", "assuntoId": "ass-reumato-cristais", "frente": "Qual é a meta de ácido úrico no tratamento da gota?", "verso": "Abaixo de 6 mg/dL, ajustando a dose do alopurinol até chegar lá (tratar até o alvo); com tofos, alguns consensos pedem abaixo de 5 mg/dL.", "fonte": "ACR 2020; EULAR 2016", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-055", "assuntoId": "ass-reumato-vasculites", "frente": "Qual é a conduta na suspeita de arterite de células gigantes?", "verso": "Corticoide em dose alta IMEDIATAMENTE, sem esperar a biópsia de artéria temporal: o risco é perda visual irreversível. Suspeitar em maiores de 50 anos com cefaleia nova, claudicação de mandíbula e VHS/PCR elevados.", "fonte": "EULAR, recomendações de vasculite de grandes vasos, 2018", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-056", "assuntoId": "ass-reumato-vasculites", "frente": "Quais são os critérios da doença de Kawasaki e o tratamento?", "verso": "Febre por 5 dias ou mais com 4 de 5: conjuntivite não exsudativa, alterações de lábios e mucosa oral, exantema, alterações de extremidades e linfonodo cervical de 1,5 cm ou mais. Tratamento: imunoglobulina venosa e AAS, para evitar aneurisma coronariano.", "fonte": "AHA, diretriz de doença de Kawasaki, 2017", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-057", "assuntoId": "ass-reumato-vasculites", "frente": "Como é a vasculite por IgA (púrpura de Henoch-Schönlein)?", "verso": "Criança com púrpura palpável em membros inferiores e nádegas, artralgia, dor abdominal e hematúria, com plaquetas normais. A complicação que dita o seguimento é a renal.", "fonte": "Critérios EULAR/PRINTO/PRES, 2010", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-058", "assuntoId": "ass-reumato-febrereumatica", "frente": "Quais são os critérios maiores de Jones para febre reumática?", "verso": "Cardite, artrite, coreia de Sydenham, eritema marginado e nódulos subcutâneos. O diagnóstico exige também evidência de infecção estreptocócica recente.", "fonte": "Critérios de Jones revisados, AHA 2015", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-059", "assuntoId": "ass-reumato-febrereumatica", "frente": "Como é feita e por quanto tempo dura a profilaxia secundária da febre reumática?", "verso": "Penicilina benzatina a cada 21 dias. Sem cardite: até 21 anos ou 5 anos após o último surto; cardite curada ou lesão leve: até 25 anos ou 10 anos após o surto; lesão moderada a grave: até 40 anos ou por toda a vida (vale o período mais longo).", "fonte": "Diretrizes brasileiras de febre reumática, SBC 2009", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-060", "assuntoId": "ass-reumato-febrereumatica", "frente": "Como se previne a febre reumática no primeiro episódio?", "verso": "Tratando a faringoamigdalite estreptocócica: penicilina benzatina em dose única (ou amoxicilina por 10 dias). O tratamento previne a febre reumática mesmo se iniciado até 9 dias após o início da faringite.", "fonte": "Diretrizes brasileiras de febre reumática, SBC 2009", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-061", "assuntoId": "ass-reumato-conectivopatias", "frente": "Como se diferenciam as formas limitada e difusa da esclerose sistêmica?", "verso": "Limitada: pele espessada só até cotovelos e joelhos (e face), anticentrômero, risco de hipertensão pulmonar tardia. Difusa: pele do tronco, anti-Scl-70, doença pulmonar intersticial e crise renal mais precoces.", "fonte": "Critérios ACR/EULAR 2013", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-062", "assuntoId": "ass-reumato-conectivopatias", "frente": "Como se trata a crise renal esclerodérmica e qual droga a precipita?", "verso": "Hipertensão acelerada com insuficiência renal aguda: trata-se com inibidor da ECA (captopril), mesmo com creatinina subindo. Corticoide em dose alta é fator de risco.", "fonte": "Recomendações EULAR para esclerose sistêmica, 2017", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-063", "assuntoId": "ass-reumato-conectivopatias", "frente": "O que caracteriza a síndrome de Sjögren?", "verso": "Olho seco e boca seca por infiltração das glândulas exócrinas, com anti-Ro/SSA e anti-La/SSB. Tem risco aumentado de linfoma, que se suspeita com aumento persistente de parótida.", "fonte": "Critérios ACR/EULAR 2016", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-064", "assuntoId": "ass-hemato-anemias", "frente": "Qual é o melhor exame para confirmar anemia ferropriva?", "verso": "Ferritina baixa, que reflete o estoque de ferro. Acompanha ferro sérico baixo, capacidade de ligação (transferrina) alta, saturação baixa e RDW alto. Em inflamação a ferritina sobe e pode enganar.", "fonte": "OMS, ferritina para avaliação do ferro, 2020", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-065", "assuntoId": "ass-hemato-anemias", "frente": "Como diferenciar talassemia minor de anemia ferropriva?", "verso": "Na talassemia minor a microcitose é intensa para uma anemia leve, o RDW é normal, a ferritina é normal e o número de hemácias é alto. Na beta-talassemia, a eletroforese mostra HbA2 aumentada.", "fonte": "ABHH; revisões de microcitose", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-066", "assuntoId": "ass-hemato-anemias", "frente": "O que distingue a deficiência de B12 da de folato?", "verso": "As duas dão anemia megaloblástica, mas só a de B12 causa alteração neurológica (degeneração combinada subaguda da medula) e ácido metilmalônico elevado. Tratar só com folato uma deficiência de B12 pode piorar a lesão neurológica.", "fonte": "British Society for Haematology, 2014", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-067", "assuntoId": "ass-hemato-neoplasias", "frente": "Qual é a leucemia mais comum na criança e qual é a mais comum no idoso?", "verso": "Leucemia linfoide aguda na infância. Leucemia linfocítica crônica em idosos: linfocitose persistente, muitas vezes descoberta em hemograma de rotina, com manchas de Gumprecht no esfregaço.", "fonte": "INCA; iwCLL 2018", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-068", "assuntoId": "ass-hemato-neoplasias", "frente": "Por que a leucemia promielocítica aguda é uma emergência e como se trata?", "verso": "Porque causa coagulação intravascular disseminada com sangramento grave logo no início. Tem a translocação t(15;17) e responde ao ácido transretinoico (ATRA), que deve começar já na suspeita.", "fonte": "ELN, recomendações de LMA, 2022", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-069", "assuntoId": "ass-hemato-neoplasias", "frente": "O que é o CRAB no mieloma múltiplo?", "verso": "Hipercalcemia, insuficiência Renal, Anemia e lesões ósseas (Bone) líticas. Com pico monoclonal na eletroforese de proteínas. A fosfatase alcalina costuma ser normal, porque a lesão é lítica pura.", "fonte": "IMWG, critérios diagnósticos, 2014", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-070", "assuntoId": "ass-hemato-hemostasia", "frente": "O que significa TP alargado isolado e TTPa alargado isolado?", "verso": "TP alargado isolado: via extrínseca (fator VII) — varfarina, falta de vitamina K, hepatopatia inicial. TTPa alargado isolado: via intrínseca (fatores VIII, IX, XI) — heparina, hemofilias, anticoagulante lúpico.", "fonte": "ABHH; revisões de coagulograma", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-071", "assuntoId": "ass-hemato-hemostasia", "frente": "Como se apresenta e quando se trata a púrpura trombocitopênica imune na criança?", "verso": "Plaquetopenia isolada com petéquias e sangramento mucoso em criança saudável, muitas vezes após virose; em geral se resolve sozinha. Trata-se (corticoide ou imunoglobulina) quando há sangramento relevante, não pelo número isolado.", "fonte": "ASH, diretriz de PTI, 2019", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-072", "assuntoId": "ass-hemato-hemostasia", "frente": "Como se reverte a varfarina num sangramento grave?", "verso": "Vitamina K venosa associada a concentrado de complexo protrombínico (ou plasma fresco congelado, se não houver). A vitamina K sozinha demora horas.", "fonte": "CHEST, 2012; ASH 2018", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-073", "assuntoId": "ass-hemato-hemoglobinopatias", "frente": "Por que febre em criança com doença falciforme é urgência?", "verso": "Porque há asplenia funcional e alto risco de sepse por germes encapsulados (pneumococo). Colhem-se culturas e dá-se antibiótico parenteral imediatamente.", "fonte": "Ministério da Saúde, Doença falciforme — condutas básicas, 2012", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-074", "assuntoId": "ass-hemato-hemoglobinopatias", "frente": "Como a hidroxiureia age na doença falciforme e para quem é indicada?", "verso": "Aumenta a hemoglobina fetal, reduzindo crises dolorosas, síndrome torácica aguda, transfusões e mortalidade. Indicada em crises frequentes, síndrome torácica prévia e outras complicações, conforme o protocolo.", "fonte": "PCDT da doença falciforme, Ministério da Saúde", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-075", "assuntoId": "ass-hemato-hemoglobinopatias", "frente": "Quais são as medidas de prevenção de infecção na criança com doença falciforme?", "verso": "Penicilina oral profilática dos 3 meses aos 5 anos e vacinação ampliada, incluindo pneumocócicas. O diagnóstico é feito pelo teste do pezinho.", "fonte": "Ministério da Saúde, Doença falciforme — condutas básicas, 2012", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-076", "assuntoId": "ass-geriatria-quedas", "frente": "Quais são os critérios do fenótipo de fragilidade de Fried?", "verso": "Perda de peso não intencional, exaustão, fraqueza (força de preensão baixa), lentidão da marcha e baixa atividade física. Três ou mais: frágil; um ou dois: pré-frágil.", "fonte": "Fried et al., 2001", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-077", "assuntoId": "ass-geriatria-quedas", "frente": "Qual é a intervenção isolada mais eficaz para prevenir quedas no idoso da comunidade?", "verso": "Exercício com treino de equilíbrio e força. Junto: revisar medicamentos (benzodiazepínicos, sedativos, anti-hipertensivos), corrigir a visão e adaptar a casa.", "fonte": "World Guidelines for Falls Prevention, 2022", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-078", "assuntoId": "ass-geriatria-quedas", "frente": "O que é o teste Timed Up and Go?", "verso": "O idoso levanta da cadeira, anda 3 metros, volta e senta. Tempo de 12 segundos ou mais indica risco aumentado de queda.", "fonte": "CDC, iniciativa STEADI", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-079", "assuntoId": "ass-geriatria-demencia", "frente": "Como diferenciar delirium de demência?", "verso": "Delirium tem início agudo, curso flutuante, déficit de atenção e alteração do nível de consciência, e sempre tem uma causa a procurar (infecção, droga, distúrbio metabólico). A demência é insidiosa e progressiva, com atenção preservada no início.", "fonte": "DSM-5-TR; Confusion Assessment Method", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-080", "assuntoId": "ass-geriatria-demencia", "frente": "Como se trata o delirium no idoso?", "verso": "Tratando a causa e com medidas não farmacológicas (orientação, óculos e aparelho auditivo, sono, mobilização, presença da família). Antipsicótico só para agitação com risco; benzodiazepínico piora, exceto na abstinência alcoólica.", "fonte": "NICE, diretriz de delirium, 2023", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-081", "assuntoId": "ass-geriatria-demencia", "frente": "Que exames procuram causas tratáveis de demência, e o que se usa no Alzheimer?", "verso": "Vitamina B12, TSH, sorologia para sífilis, exames gerais e imagem do crânio. No Alzheimer leve a moderado, inibidores da colinesterase (donepezila, rivastigmina, galantamina); na fase moderada a grave, memantina.", "fonte": "Academia Brasileira de Neurologia, 2022", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-082", "assuntoId": "ass-geriatria-polifarmacia", "frente": "O que são os critérios de Beers?", "verso": "Lista de medicamentos potencialmente inapropriados para idosos, como benzodiazepínicos, anticolinérgicos (amitriptilina, prometazina, hidroxizina) e anti-inflamatório de uso crônico.", "fonte": "American Geriatrics Society, critérios de Beers 2023", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-083", "assuntoId": "ass-geriatria-polifarmacia", "frente": "O que é cascata iatrogênica?", "verso": "Um efeito adverso de um remédio é interpretado como doença nova e tratado com outro remédio. Exemplo: edema pelo bloqueador de canal de cálcio tratado com diurético.", "fonte": "Rochon & Gurwitz, BMJ 1997", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-084", "assuntoId": "ass-geriatria-polifarmacia", "frente": "Por que anticolinérgicos são tão perigosos no idoso?", "verso": "Causam confusão e delirium, retenção urinária, constipação, boca seca e quedas, e se somam entre si (carga anticolinérgica). Sempre que possível, trocar por alternativa.", "fonte": "American Geriatrics Society, critérios de Beers 2023", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-085", "assuntoId": "ass-geriatria-maustratos", "frente": "O que o médico deve fazer diante de suspeita de violência contra a pessoa idosa?", "verso": "Notificar (notificação compulsória, no SINAN) e comunicar às autoridades competentes, além de proteger o idoso. A suspeita basta — não é preciso confirmar.", "fonte": "Estatuto da Pessoa Idosa, Lei 10.741/2003; Lei 12.461/2011", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-086", "assuntoId": "ass-geriatria-maustratos", "frente": "Quem costuma ser o agressor da pessoa idosa?", "verso": "Na maioria das vezes um familiar próximo, frequentemente filho(a) ou cuidador, dentro de casa — e os tipos de violência se somam (física, psicológica, financeira, negligência).", "fonte": "Ministério da Saúde, violência contra a pessoa idosa", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-087", "assuntoId": "ass-geriatria-maustratos", "frente": "Que sinais sugerem maus-tratos ao idoso?", "verso": "Lesões em estágios diferentes de cicatrização, explicação que não combina com a lesão, demora em procurar atendimento, desnutrição, desidratação, lesões por pressão sem cuidado e medo do cuidador.", "fonte": "Ministério da Saúde, Caderno de Atenção Básica 19", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-088", "assuntoId": "ass-genetica-heranca", "frente": "Quais são os sinais de herança autossômica dominante no heredograma?", "verso": "Afeta homens e mulheres, aparece em todas as gerações e cada filho de um afetado tem 50% de chance de herdar. Exemplos: neurofibromatose tipo 1, doença de Huntington, síndrome de Marfan.", "fonte": "Thompson & Thompson, Genética Médica", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-089", "assuntoId": "ass-genetica-heranca", "frente": "Como se reconhece a herança recessiva ligada ao X?", "verso": "Quase só homens afetados, mães portadoras, e não há transmissão de pai para filho homem. Exemplos: hemofilias A e B, distrofia de Duchenne, daltonismo.", "fonte": "Thompson & Thompson, Genética Médica", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-090", "assuntoId": "ass-genetica-heranca", "frente": "Qual é a regra da herança mitocondrial?", "verso": "Só a mãe transmite: todos os filhos de uma mulher afetada podem ser afetados, e homens afetados não transmitem. A gravidade varia pela proporção de mitocôndrias alteradas (heteroplasmia).", "fonte": "Thompson & Thompson, Genética Médica", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-091", "assuntoId": "ass-genetica-sindromes", "frente": "Quais são os achados da síndrome de Down e a cardiopatia mais característica?", "verso": "Hipotonia, fendas palpebrais oblíquas, prega palmar única, deficiência intelectual. A cardiopatia mais característica é o defeito do septo atrioventricular; rastreiam-se também hipotireoidismo e alterações hematológicas.", "fonte": "SBP, Diretrizes de atenção à pessoa com síndrome de Down, 2020", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-092", "assuntoId": "ass-genetica-sindromes", "frente": "Como se apresenta a síndrome de Turner?", "verso": "Menina com baixa estatura, pescoço alado, linfedema de mãos e pés ao nascer e amenorreia primária por disgenesia gonadal (cariótipo 45,X). Associa-se a coarctação da aorta e valva aórtica bicúspide.", "fonte": "Diretriz internacional de síndrome de Turner, 2017", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-093", "assuntoId": "ass-genetica-sindromes", "frente": "Qual é o quadro da síndrome de Klinefelter?", "verso": "Homem alto, com testículos pequenos e firmes, ginecomastia e infertilidade por azoospermia; hipogonadismo hipergonadotrófico (FSH e LH altos, testosterona baixa); cariótipo 47,XXY.", "fonte": "Revisões de síndrome de Klinefelter; SBEM", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-094", "assuntoId": "ass-anestesio-viaaerea", "frente": "O que é a intubação em sequência rápida e por que se faz?", "verso": "Pré-oxigenação, seguida de hipnótico e bloqueador neuromuscular em sequência imediata, evitando ventilar com pressão enquanto a droga age. Serve para intubar rápido quem tem risco de aspiração (estômago cheio).", "fonte": "Difficult Airway Society; Diretriz de via aérea da SBA", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-095", "assuntoId": "ass-anestesio-viaaerea", "frente": "Quando a succinilcolina é contraindicada?", "verso": "Hipercalemia, grandes queimados, esmagamentos e lesões com desnervação após as primeiras 24 a 72 horas, miopatias e história pessoal ou familiar de hipertermia maligna. Nesses casos, usa-se rocurônio.", "fonte": "Miller's Anesthesia; SBA", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-096", "assuntoId": "ass-anestesio-viaaerea", "frente": "O que avalia a classificação de Mallampati?", "verso": "O quanto se vê da orofaringe com a boca aberta e a língua para fora (classes I a IV). Classes III e IV predizem laringoscopia difícil.", "fonte": "Mallampati, 1985; SBA", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-097", "assuntoId": "ass-anestesio-complicacoes", "frente": "Como se reconhece e se trata a hipertermia maligna?", "verso": "Durante anestesia com halogenado ou succinilcolina: aumento inexplicado do CO2 expirado (sinal precoce), taquicardia, rigidez muscular e, mais tarde, hipertermia. Suspende-se o agente e dá-se dantroleno venoso.", "fonte": "European Malignant Hyperthermia Group, 2020", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-098", "assuntoId": "ass-anestesio-complicacoes", "frente": "Quais são os sinais da intoxicação por anestésico local e o tratamento específico?", "verso": "Primeiro sintomas neurológicos (gosto metálico, zumbido, formigamento perioral, convulsão), depois cardiovasculares (arritmia, parada). O tratamento específico é a emulsão lipídica a 20%. A bupivacaína é a mais cardiotóxica.", "fonte": "ASRA, recomendações de LAST, 2020", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-099", "assuntoId": "ass-anestesio-complicacoes", "frente": "Como é a cefaleia pós-punção dural e como se trata quando não melhora?", "verso": "Cefaleia que piora sentado ou em pé e melhora deitado, 24 a 48 horas após raquianestesia ou punção acidental. Tratamento inicial conservador; se persistir, tampão sanguíneo peridural.", "fonte": "Consenso internacional de cefaleia pós-punção dural, 2023", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-100", "assuntoId": "ass-anestesio-analgesia", "frente": "Qual é a diferença prática entre raquianestesia e peridural?", "verso": "A raqui é feita no espaço subaracnóideo, com pequena dose, início rápido e bloqueio denso. A peridural usa volume maior no espaço peridural, tem início mais lento e permite deixar cateter para analgesia contínua (como no trabalho de parto).", "fonte": "SBA; Miller's Anesthesia", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-101", "assuntoId": "ass-anestesio-analgesia", "frente": "Como é a escada analgésica da OMS?", "verso": "Degrau 1: analgésico não opioide (dipirona, paracetamol, anti-inflamatório); degrau 2: opioide fraco (codeína, tramadol); degrau 3: opioide forte (morfina). Adjuvantes podem entrar em qualquer degrau.", "fonte": "OMS, alívio da dor no câncer", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-102", "assuntoId": "ass-anestesio-analgesia", "frente": "Por que a anticoagulação importa antes de raqui ou peridural?", "verso": "Pelo risco de hematoma espinhal, que pode causar paraplegia. Respeitam-se intervalos: por exemplo, 12 horas após enoxaparina profilática e 24 horas após dose terapêutica.", "fonte": "ASRA, diretriz de anticoagulação e bloqueio neuroaxial, 2018", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-103", "assuntoId": "ass-cirvasc-aneurisma", "frente": "Quando se indica a correção eletiva do aneurisma de aorta abdominal?", "verso": "Diâmetro de 5,5 cm ou mais em homens (5,0 cm em mulheres), crescimento maior que 0,5 cm em 6 meses ou 1 cm em um ano, ou aneurisma sintomático.", "fonte": "Society for Vascular Surgery, diretriz de AAA, 2018", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-104", "assuntoId": "ass-cirvasc-aneurisma", "frente": "Quem deve fazer rastreamento de aneurisma de aorta abdominal?", "verso": "Homens de 65 a 75 anos que fumam ou já fumaram: ultrassonografia de abdome uma única vez.", "fonte": "USPSTF, 2019", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-105", "assuntoId": "ass-cirvasc-aneurisma", "frente": "Qual é a conduta no aneurisma de aorta abdominal roto com instabilidade?", "verso": "Dor abdominal ou lombar, hipotensão e massa pulsátil: vai direto ao centro cirúrgico, sem tomografia, com hipotensão permissiva até o controle vascular.", "fonte": "Society for Vascular Surgery, 2018", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-106", "assuntoId": "ass-cirvasc-arterial", "frente": "Quais são os sinais de isquemia arterial aguda de membro e a primeira conduta?", "verso": "Os 6 Ps: dor, palidez, ausência de pulso, parestesia, paralisia e frialdade. Heparina venosa imediatamente e avaliação vascular de urgência; paralisia e perda de sensibilidade indicam membro ameaçado.", "fonte": "ESVS, diretriz de isquemia aguda de membro, 2020", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-107", "assuntoId": "ass-cirvasc-arterial", "frente": "Como se interpreta o índice tornozelo-braço?", "verso": "Menor que 0,9: doença arterial periférica. Maior que 1,3–1,4: artérias incompressíveis por calcificação (diabetes, doença renal crônica), e o exame não é confiável.", "fonte": "AHA/ACC, diretriz de doença arterial periférica, 2016", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-108", "assuntoId": "ass-cirvasc-arterial", "frente": "Qual é o tratamento inicial da claudicação intermitente?", "verso": "Parar de fumar, exercício supervisionado, antiagregante plaquetário e estatina. Cilostazol melhora a distância de marcha. Revascularização se a limitação continuar importante.", "fonte": "AHA/ACC 2016; ESC 2017", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-109", "assuntoId": "ass-cirvasc-venosa", "frente": "Como se investiga a suspeita de trombose venosa profunda?", "verso": "Probabilidade clínica pelo escore de Wells: baixa probabilidade com D-dímero negativo exclui; nos demais casos, ultrassonografia Doppler venosa com compressão.", "fonte": "ASH, diretriz de diagnóstico de TEV, 2018", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-110", "assuntoId": "ass-cirvasc-venosa", "frente": "Como se trata a trombose venosa profunda e por quanto tempo?", "verso": "Anticoagulação por pelo menos 3 meses. Anticoagulantes orais diretos (rivaroxabana, apixabana) são preferidos na maioria; na gestação, heparina de baixo peso molecular.", "fonte": "CHEST, diretriz de TEV, 2021", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-111", "assuntoId": "ass-cirvasc-venosa", "frente": "Onde fica e como se trata a úlcera venosa típica?", "verso": "Na região do maléolo medial, sobre pele com hiperpigmentação e lipodermatoesclerose. A base do tratamento é a compressão elástica ou inelástica.", "fonte": "ESVS, diretriz de doença venosa crônica, 2022", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-112", "assuntoId": "ass-cirvasc-disseccao", "frente": "Qual é a diferença de conduta entre dissecção de aorta Stanford A e B?", "verso": "Stanford A (envolve a aorta ascendente): cirurgia de emergência. Stanford B (só a descendente): tratamento clínico, com intervenção se houver complicação (ruptura, má perfusão).", "fonte": "ESC, diretriz de doenças da aorta, 2014/2024", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-113", "assuntoId": "ass-cirvasc-disseccao", "frente": "Como se controla a pressão na dissecção aguda de aorta?", "verso": "Betabloqueador venoso primeiro (frequência cardíaca perto de 60), depois vasodilatador se necessário, buscando pressão sistólica de 100 a 120 mmHg. Vasodilatador sem betabloqueio aumenta a força de cisalhamento.", "fonte": "ACC/AHA, diretriz de doenças da aorta, 2022", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-114", "assuntoId": "ass-cirvasc-disseccao", "frente": "Qual é o quadro clássico da dissecção de aorta e o exame de escolha no paciente estável?", "verso": "Dor torácica súbita e lancinante que irradia para o dorso, diferença de pulso ou pressão entre os braços e mediastino alargado. No estável, angiotomografia de aorta.", "fonte": "ACC/AHA 2022", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-115", "assuntoId": "ass-cirtorax-pleura", "frente": "Como se diagnostica e se trata o pneumotórax hipertensivo?", "verso": "É diagnóstico clínico — dispneia, hipotensão, murmúrio abolido, desvio de traqueia e turgência jugular — e não espera radiografia: descompressão imediata com agulha (no adulto, 4º ou 5º espaço intercostal na linha axilar média) e depois drenagem torácica.", "fonte": "ATLS, 10ª edição", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-116", "assuntoId": "ass-cirtorax-pleura", "frente": "Quais são os critérios de Light para derrame pleural exsudativo?", "verso": "Proteína pleural/sérica maior que 0,5, LDH pleural/sérica maior que 0,6 ou LDH pleural maior que 2/3 do limite superior do normal sérico. Basta um.", "fonte": "Light, 1972; BTS, diretriz de doença pleural, 2023", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-117", "assuntoId": "ass-cirtorax-pleura", "frente": "Quando o derrame parapneumônico precisa de drenagem?", "verso": "Quando é complicado ou empiema: pus, pH menor que 7,2, glicose menor que 60 mg/dL ou Gram/cultura positivos — e também nos derrames grandes ou loculados.", "fonte": "BTS, diretriz de infecção pleural, 2023", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-118", "assuntoId": "ass-cirtorax-neoplasia", "frente": "Quem deve fazer rastreamento de câncer de pulmão?", "verso": "Pessoas de 50 a 80 anos com carga tabágica de 20 anos-maço ou mais, que fumam ou pararam há menos de 15 anos: tomografia de tórax de baixa dose anual.", "fonte": "USPSTF, 2021", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-119", "assuntoId": "ass-cirtorax-neoplasia", "frente": "Que características de um nódulo pulmonar sugerem malignidade?", "verso": "Tamanho maior que 8 mm, bordas espiculadas, crescimento em exames seriados, componente sólido em nódulo em vidro fosco, localização em lobo superior, além de idade e tabagismo.", "fonte": "Fleischner Society, 2017", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-120", "assuntoId": "ass-cirtorax-neoplasia", "frente": "O que é a síndrome de Pancoast?", "verso": "Tumor do ápice pulmonar que invade o plexo braquial e a cadeia simpática: dor no ombro e braço e síndrome de Horner (ptose, miose e anidrose do mesmo lado).", "fonte": "Revisões de tumores do sulco superior", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-121", "assuntoId": "ass-cirtorax-viaaerea", "frente": "Como surge a estenose traqueal pós-intubação e como se previne?", "verso": "Por isquemia da mucosa comprimida pelo balonete (ou pela cânula de traqueostomia), dando estridor e dispneia semanas depois. Previne-se mantendo a pressão do balonete entre 20 e 30 cmH2O.", "fonte": "Revisões de estenose traqueal; AMIB", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-122", "assuntoId": "ass-cirtorax-viaaerea", "frente": "O que o tipo de estridor diz sobre o local da obstrução?", "verso": "Estridor inspiratório sugere obstrução extratorácica (laringe, traqueia alta); expiratório ou sibilância, obstrução intratorácica; bifásico, obstrução fixa ou na região glótica/subglótica.", "fonte": "Fisiologia da via aérea; ORL", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-123", "assuntoId": "ass-cirtorax-viaaerea", "frente": "Como se diagnostica e retira um corpo estranho brônquico na criança?", "verso": "Suspeita: engasgo seguido de tosse e sibilância localizada. A radiografia pode ser normal (ou mostrar aprisionamento de ar). Broncoscopia rígida diagnostica e retira.", "fonte": "SBP; Sociedade Brasileira de Cirurgia Torácica", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-124", "assuntoId": "ass-cirtorax-esofago", "frente": "O que é a síndrome de Boerhaave e sua tríade?", "verso": "Ruptura espontânea do esôfago após vômitos intensos, geralmente no esôfago distal à esquerda. Tríade de Mackler: vômitos, dor torácica e enfisema subcutâneo.", "fonte": "Revisões de perfuração esofágica; WSES 2019", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-125", "assuntoId": "ass-cirtorax-esofago", "frente": "Qual exame confirma a perfuração esofágica?", "verso": "Tomografia com contraste oral ou esofagograma com contraste hidrossolúvel (não bário, que irrita o mediastino).", "fonte": "WSES, diretriz de perfuração esofágica, 2019", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-126", "assuntoId": "ass-cirtorax-esofago", "frente": "Como se trata a síndrome de Boerhaave?", "verso": "Jejum, antibiótico de amplo espectro (com cobertura para fungos), suporte e reparo cirúrgico ou drenagem o mais cedo possível, idealmente nas primeiras 24 horas.", "fonte": "WSES 2019", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-127", "assuntoId": "ass-orto-fraturas", "frente": "Qual é a conduta inicial na fratura exposta?", "verso": "Antibiótico venoso o quanto antes (cefazolina; nas lesões graves, associar cobertura para gram-negativos), profilaxia antitetânica, cobertura estéril da ferida e desbridamento com lavagem no centro cirúrgico.", "fonte": "Classificação de Gustilo; BOA/BAPRAS 2017", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-128", "assuntoId": "ass-orto-fraturas", "frente": "Como se reconhece e se trata a síndrome compartimental?", "verso": "Dor desproporcional à lesão, que piora com o estiramento passivo dos músculos do compartimento; o pulso pode estar presente até tarde. Tratamento: fasciotomia de urgência.", "fonte": "BOA Standards, síndrome compartimental", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-129", "assuntoId": "ass-orto-fraturas", "frente": "Qual é a apresentação típica da fratura do colo do fêmur no idoso e a conduta?", "verso": "Após queda, membro encurtado e em rotação externa, com dor no quadril e incapacidade de andar. Tratamento cirúrgico precoce, idealmente em até 48 horas.", "fonte": "NICE, fratura de quadril, 2023", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-130", "assuntoId": "ass-orto-osteometabolicas", "frente": "Como se define osteoporose pela densitometria?", "verso": "T-score de −2,5 ou menor em colo do fêmur, fêmur total ou coluna lombar, em mulheres na pós-menopausa e homens a partir de 50 anos. Fratura por fragilidade define a doença independentemente do exame.", "fonte": "OMS; diretriz brasileira de osteoporose (ABRASSO/SBR)", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-131", "assuntoId": "ass-orto-osteometabolicas", "frente": "Quais são os sinais do raquitismo carencial?", "verso": "Alargamento de punhos e tornozelos, rosário raquítico, pernas arqueadas (geno varo), atraso de fechamento da fontanela, com fosfatase alcalina elevada. Causa mais comum: falta de vitamina D.", "fonte": "Consenso global de raquitismo nutricional, 2016", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-132", "assuntoId": "ass-orto-osteometabolicas", "frente": "O que é osteogênese imperfeita e por que ela importa no pronto-socorro?", "verso": "Defeito do colágeno tipo I com fraturas de repetição, escleras azuladas e perda auditiva. Importa porque é diagnóstico diferencial de maus-tratos na criança com várias fraturas.", "fonte": "Revisões de osteogênese imperfeita; SBP", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-133", "assuntoId": "ass-orto-pediatrica", "frente": "Como se rastreia a displasia do desenvolvimento do quadril?", "verso": "Manobras de Ortolani (redução) e Barlow (luxação) no exame do recém-nascido; ultrassonografia até cerca de 4 a 6 meses nos casos suspeitos ou de risco (pélvico, história familiar). Tratamento com suspensório de Pavlik.", "fonte": "SBOP; AAP 2016", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-134", "assuntoId": "ass-orto-pediatrica", "frente": "O que é a doença de Legg-Calvé-Perthes?", "verso": "Necrose avascular da cabeça do fêmur em meninos de 4 a 8 anos, com claudicação e dor que pode ser referida no joelho.", "fonte": "SBOP; revisões de ortopedia pediátrica", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-135", "assuntoId": "ass-orto-pediatrica", "frente": "Como se apresenta a epifisiólise proximal do fêmur?", "verso": "Adolescente, muitas vezes obeso, com dor no quadril ou no joelho e claudicação; ao fletir o quadril, a coxa roda para fora (sinal de Drehmann). Tratamento cirúrgico: fixação in situ, sem tentar reduzir.", "fonte": "SBOP; revisões de epifisiólise", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-136", "assuntoId": "ass-orto-infeccoes", "frente": "Onde se localiza e qual é o agente mais comum da osteomielite hematogênica da criança?", "verso": "Metáfise dos ossos longos, por Staphylococcus aureus. A ressonância é o exame mais sensível no início, quando a radiografia ainda é normal.", "fonte": "IDSA/PIDS, diretriz de osteomielite pediátrica, 2021", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-137", "assuntoId": "ass-orto-infeccoes", "frente": "Quais são os critérios de Kocher para artrite séptica do quadril na criança?", "verso": "Febre acima de 38,5 °C, recusa em apoiar o membro, VHS acima de 40 mm/h e leucócitos acima de 12.000. Quanto mais critérios, maior a probabilidade; artrite séptica é urgência de drenagem.", "fonte": "Kocher et al., 1999", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-138", "assuntoId": "ass-orto-infeccoes", "frente": "Que agente, além do estafilococo, causa osteomielite na doença falciforme?", "verso": "Salmonella, pela asplenia funcional e pelos infartos ósseos. O antibiótico empírico precisa cobri-la.", "fonte": "Revisões de doença falciforme; IDSA", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-139", "assuntoId": "ass-orto-artrose", "frente": "Como é a dor da osteoartrite e o que mostra a radiografia?", "verso": "Dor mecânica, que piora com o uso e melhora com o repouso, com rigidez matinal curta (menos de 30 minutos). Radiografia: redução do espaço articular, osteófitos, esclerose subcondral e cistos.", "fonte": "ACR, diretriz de osteoartrite, 2019", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-140", "assuntoId": "ass-orto-artrose", "frente": "Qual é o tratamento inicial da osteoartrite de joelho?", "verso": "Exercício (fortalecimento) e perda de peso, com analgésico e anti-inflamatório tópico. Infiltração de corticoide nas crises; artroplastia quando refratária e incapacitante.", "fonte": "ACR 2019; OARSI 2019", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-141", "assuntoId": "ass-orto-artrose", "frente": "O que são os nódulos de Heberden e de Bouchard?", "verso": "Nódulos ósseos da osteoartrite nas interfalângicas distais (Heberden) e proximais (Bouchard). A artrite reumatoide poupa as interfalângicas distais.", "fonte": "ACR; semiologia reumatológica", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-142", "assuntoId": "ass-orto-ligamentos", "frente": "Como se suspeita e se confirma a lesão do ligamento cruzado anterior?", "verso": "Entorse com torção, estalo e derrame articular rápido (hemartrose). Teste de Lachman (o mais sensível) e gaveta anterior; confirmação por ressonância.", "fonte": "Revisões de lesões ligamentares do joelho; SBOT", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-143", "assuntoId": "ass-orto-ligamentos", "frente": "O que é a tríade infeliz de O'Donoghue?", "verso": "Lesão combinada do ligamento cruzado anterior, do ligamento colateral medial e do menisco, após trauma em valgo com rotação do joelho.", "fonte": "O'Donoghue, 1950", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-144", "assuntoId": "ass-orto-ligamentos", "frente": "Que teste do exame físico sugere lesão de menisco?", "verso": "O teste de McMurray: dor ou estalido ao estender o joelho com rotação da tíbia. Dor na interlinha articular também sugere lesão meniscal.", "fonte": "Semiologia ortopédica; SBOT", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-145", "assuntoId": "ass-orto-ombro", "frente": "Qual é a luxação de ombro mais comum e o nervo a examinar?", "verso": "A anterior (mais de 95%), com o braço em abdução e rotação externa. Examina-se o nervo axilar (sensibilidade na face lateral do ombro) antes e depois da redução.", "fonte": "SBOT; revisões de luxação glenoumeral", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-146", "assuntoId": "ass-orto-ombro", "frente": "Qual tendão do manguito rotador mais se lesa e como se testa?", "verso": "O supraespinal, testado pela manobra de Jobe; arco doloroso entre 60 e 120 graus de abdução sugere impacto.", "fonte": "SBOT; semiologia ortopédica", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-147", "assuntoId": "ass-orto-ombro", "frente": "Em que situações se pensa em luxação posterior do ombro?", "verso": "Após crise convulsiva e choque elétrico. É a luxação mais deixada passar, porque a radiografia só de frente pode parecer normal.", "fonte": "Revisões de luxação posterior do ombro", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-148", "assuntoId": "ass-orto-coluna", "frente": "Quais são os sinais de alarme na lombalgia?", "verso": "Febre, perda de peso, câncer prévio, trauma importante, dor que não melhora com repouso, déficit neurológico progressivo, sintomas de cauda equina e início após os 50 anos. Sem eles, a lombalgia aguda não precisa de imagem.", "fonte": "ACP, diretriz de lombalgia, 2017", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-149", "assuntoId": "ass-orto-coluna", "frente": "Como se reconhece a síndrome da cauda equina e qual é a conduta?", "verso": "Retenção urinária, anestesia em sela e fraqueza nas pernas, muitas vezes bilateral. Ressonância e descompressão cirúrgica de urgência.", "fonte": "NICE; revisões de cauda equina", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-150", "assuntoId": "ass-orto-coluna", "frente": "Que raiz é comprimida numa hérnia L4-L5 e numa L5-S1?", "verso": "L4-L5 costuma comprimir a raiz L5: fraqueza para estender o hálux e dorsofletir o pé, dormência no dorso do pé. L5-S1 comprime S1: reflexo aquileu diminuído, fraqueza de flexão plantar, dormência na borda lateral do pé.", "fonte": "Semiologia neurológica; NASS", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-151", "assuntoId": "ass-uro-litiase", "frente": "Qual é o exame de escolha na cólica renal e as exceções?", "verso": "Tomografia de abdome sem contraste (de preferência em baixa dose). Em gestantes e crianças, ultrassonografia.", "fonte": "EAU, diretriz de litíase, 2024", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-152", "assuntoId": "ass-uro-litiase", "frente": "Quando se tenta a eliminação espontânea de um cálculo ureteral?", "verso": "Cálculo de até 10 mm (sobretudo até 5 mm), com dor controlada, sem infecção e com rim funcionante: analgesia e terapia expulsiva com alfabloqueador (tansulosina).", "fonte": "EAU 2024; AUA 2016", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-153", "assuntoId": "ass-uro-litiase", "frente": "O que fazer quando há cálculo obstrutivo com febre?", "verso": "É emergência: desobstruir o rim (cateter duplo J ou nefrostomia) e dar antibiótico. O cálculo só é tratado depois que a infecção passa.", "fonte": "EAU 2024", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-154", "assuntoId": "ass-uro-prostata", "frente": "Como agem os dois principais remédios da hiperplasia prostática benigna?", "verso": "O alfabloqueador (tansulosina, doxazosina) relaxa a musculatura e alivia em dias. O inibidor da 5-alfa-redutase (finasterida) reduz o volume da próstata em meses, serve para próstatas grandes e diminui o PSA pela metade.", "fonte": "AUA, diretriz de HPB, 2021", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-155", "assuntoId": "ass-uro-prostata", "frente": "Qual é a conduta inicial na retenção urinária aguda?", "verso": "Esvaziar a bexiga com sondagem vesical de alívio ou de demora, e depois investigar a causa (HPB, medicamentos anticolinérgicos, constipação).", "fonte": "AUA; EAU", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-156", "assuntoId": "ass-uro-prostata", "frente": "Onde se localiza o câncer de próstata e qual é a posição brasileira sobre o rastreamento?", "verso": "A maioria surge na zona periférica, palpável ao toque retal; o diagnóstico é por biópsia. O INCA e o Ministério da Saúde não recomendam rastreamento populacional; a decisão é individual, após explicar riscos e benefícios.", "fonte": "INCA, 2023; USPSTF 2018", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-157", "assuntoId": "ass-uro-escroto", "frente": "Quais são os sinais da torção testicular e qual é a conduta?", "verso": "Dor escrotal súbita e intensa, testículo elevado e horizontalizado, reflexo cremastérico ausente. Exploração cirúrgica imediata, idealmente em até 6 horas — o exame de imagem não pode atrasar a cirurgia quando a clínica é típica.", "fonte": "EAU, urologia pediátrica, 2024", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-158", "assuntoId": "ass-uro-escroto", "frente": "Como diferenciar epididimite de torção, e como se trata a epididimite no homem jovem?", "verso": "Na epididimite a dor é gradual, o reflexo cremastérico está presente e a dor alivia ao elevar o testículo (sinal de Prehn). No homem sexualmente ativo com menos de 35 anos, cobre-se gonococo e clamídia: ceftriaxona mais doxiciclina.", "fonte": "CDC, IST 2021; PCDT IST, Ministério da Saúde 2022", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-159", "assuntoId": "ass-uro-escroto", "frente": "Quando se opera a criptorquidia e por quê?", "verso": "Orquidopexia entre 6 e 18 meses: preserva a fertilidade, facilita o exame e reduz risco de torção; o risco de câncer continua maior que o da população, mas o testículo fica palpável.", "fonte": "AUA, diretriz de criptorquidia, 2014/2018", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-160", "assuntoId": "ass-uro-malformacoes", "frente": "Como se diagnostica o refluxo vesicoureteral e por que ele importa?", "verso": "Pela uretrocistografia miccional. Importa porque causa infecção urinária febril de repetição e cicatriz renal.", "fonte": "AAP, ITU febril 2011/2016; EAU pediátrica", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-161", "assuntoId": "ass-uro-malformacoes", "frente": "O que é a válvula de uretra posterior?", "verso": "Causa mais comum de obstrução urinária baixa em meninos: hidronefrose bilateral, bexiga espessada, oligoidrâmnio e jato urinário fraco; pode levar a doença renal crônica.", "fonte": "EAU, urologia pediátrica, 2024", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-162", "assuntoId": "ass-uro-malformacoes", "frente": "Qual é a causa obstrutiva mais comum de hidronefrose detectada no pré-natal?", "verso": "Estenose da junção ureteropélvica. Grande parte das hidronefroses antenatais, porém, é transitória e se resolve sozinha.", "fonte": "SFU; EAU pediátrica", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-163", "assuntoId": "ass-uro-oncologia", "frente": "O que se sabe sobre a apresentação do carcinoma de células renais?", "verso": "A tríade de hematúria, dor lombar e massa palpável é rara; hoje ele costuma ser achado de imagem. Pode dar síndromes paraneoplásicas (policitemia, hipercalcemia) e associa-se a tabagismo e doença de von Hippel-Lindau.", "fonte": "EAU, diretriz de câncer renal, 2024", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-164", "assuntoId": "ass-uro-oncologia", "frente": "Hematúria macroscópica indolor num tabagista: o que investigar?", "verso": "Câncer de bexiga (carcinoma urotelial): cistoscopia e imagem do trato urinário superior.", "fonte": "EAU, câncer de bexiga, 2024", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-165", "assuntoId": "ass-uro-oncologia", "frente": "Como se investiga e se opera uma massa testicular?", "verso": "Ultrassonografia e marcadores (AFP, beta-hCG, LDH); tratamento com orquiectomia radical por via inguinal — nunca biópsia ou cirurgia pelo escroto, que muda a drenagem linfática.", "fonte": "EAU, câncer de testículo, 2024", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-166", "assuntoId": "ass-uro-disfuncaoeretil", "frente": "Qual é a contraindicação absoluta dos inibidores da fosfodiesterase-5?", "verso": "Uso de nitratos (ou doadores de óxido nítrico): a associação causa hipotensão grave.", "fonte": "AUA, disfunção erétil, 2018", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-167", "assuntoId": "ass-uro-disfuncaoeretil", "frente": "Por que a disfunção erétil deve levar a avaliar o coração?", "verso": "Porque pode ser marcador precoce de doença cardiovascular, aparecendo anos antes de um evento coronariano. Investigar diabetes, dislipidemia, hipertensão e tabagismo.", "fonte": "Princeton Consensus; AUA 2018", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-168", "assuntoId": "ass-uro-disfuncaoeretil", "frente": "Qual é a conduta no priapismo isquêmico?", "verso": "Ereção dolorosa com mais de 4 horas é emergência: aspiração dos corpos cavernosos e injeção de fenilefrina; cirurgia se não resolver.", "fonte": "AUA, priapismo, 2022", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-169", "assuntoId": "ass-neurocir-tce", "frente": "Como diferenciar hematoma extradural de subdural na tomografia e na história?", "verso": "Extradural: sangramento arterial (artéria meníngea média), imagem biconvexa em lente, muitas vezes com intervalo lúcido. Subdural: veias-ponte, imagem em crescente que acompanha o crânio, comum em idosos e alcoolistas.", "fonte": "Brain Trauma Foundation; ATLS 10ª edição", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-170", "assuntoId": "ass-neurocir-tce", "frente": "Qual pontuação na escala de Glasgow define TCE grave e o que ela exige?", "verso": "Glasgow 8 ou menos: TCE grave, com indicação de intubação para proteger a via aérea e evitar hipóxia e hipercapnia, que agravam a lesão cerebral.", "fonte": "ATLS 10ª edição; Brain Trauma Foundation 2016", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-171", "assuntoId": "ass-neurocir-tce", "frente": "O que é a tríade de Cushing?", "verso": "Hipertensão arterial, bradicardia e respiração irregular: sinal tardio de hipertensão intracraniana grave e herniação iminente.", "fonte": "ATLS 10ª edição", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-172", "assuntoId": "ass-neurocir-tumores", "frente": "Qual é o tumor cerebral maligno primário mais comum no adulto, e o que é mais comum que ele?", "verso": "Glioblastoma é o primário maligno mais comum; mas os tumores intracranianos mais frequentes no adulto são as metástases (pulmão, mama, melanoma, rim).", "fonte": "Classificação da OMS de tumores do SNC, 2021", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-173", "assuntoId": "ass-neurocir-tumores", "frente": "Onde ficam os tumores cerebrais da criança?", "verso": "A maioria na fossa posterior: meduloblastoma, astrocitoma pilocítico e ependimoma, que podem causar hidrocefalia, ataxia e vômitos matinais.", "fonte": "OMS 2021; SOBOPE", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-174", "assuntoId": "ass-neurocir-tumores", "frente": "Como se trata o edema cerebral ao redor de um tumor?", "verso": "Com dexametasona, que reduz o edema vasogênico. Não funciona para o edema citotóxico do AVC isquêmico.", "fonte": "EANO; revisões de edema peritumoral", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-175", "assuntoId": "ass-neurocir-hidrocefalia", "frente": "Qual é a tríade da hidrocefalia de pressão normal?", "verso": "Alteração da marcha, incontinência urinária e declínio cognitivo. É uma das causas potencialmente reversíveis de demência, com derivação ventricular.", "fonte": "Diretrizes internacionais de HPN, 2005/2021", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-176", "assuntoId": "ass-neurocir-hidrocefalia", "frente": "Como se apresenta a hidrocefalia no lactente?", "verso": "Aumento rápido do perímetro cefálico, fontanela abaulada, suturas afastadas, veias do couro cabeludo dilatadas e olhar para baixo (sinal do sol poente).", "fonte": "SBP; neurocirurgia pediátrica", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-177", "assuntoId": "ass-neurocir-hidrocefalia", "frente": "Que sinais sugerem disfunção de derivação ventriculoperitoneal?", "verso": "Cefaleia, vômitos, sonolência, irritabilidade e, no lactente, fontanela tensa. Tomografia de crânio e avaliação neurocirúrgica: obstrução e infecção são as causas mais comuns.", "fonte": "Revisões de complicações de DVP", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-178", "assuntoId": "ass-neurocir-plexobraquial", "frente": "O que é a paralisia de Erb-Duchenne?", "verso": "Lesão das raízes C5-C6 (tronco superior), em geral por distocia de ombro: braço aduzido e rodado para dentro, antebraço estendido e pronado (\"gorjeta do garçom\"), com preensão preservada.", "fonte": "Revisões de paralisia braquial obstétrica", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-179", "assuntoId": "ass-neurocir-plexobraquial", "frente": "O que é a paralisia de Klumpke?", "verso": "Lesão de C8-T1 (tronco inferior): mão em garra, fraqueza dos músculos intrínsecos, e pode vir com síndrome de Horner pela lesão da via simpática em T1.", "fonte": "Revisões de paralisia braquial obstétrica", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-180", "assuntoId": "ass-neurocir-plexobraquial", "frente": "Qual é a evolução da paralisia braquial obstétrica e quando se pensa em cirurgia?", "verso": "A maioria melhora nos primeiros meses, com fisioterapia. Sem recuperação do bíceps entre 3 e 6 meses, encaminha-se para avaliação cirúrgica.", "fonte": "Revisões de paralisia braquial obstétrica", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-181", "assuntoId": "ass-orl-fratura", "frente": "Por que o hematoma de septo nasal precisa ser drenado com urgência?", "verso": "Porque separa a cartilagem da sua irrigação: sem drenagem, evolui para necrose, abscesso e nariz em sela.", "fonte": "ABORL-CCF; revisões de trauma nasal", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-182", "assuntoId": "ass-orl-fratura", "frente": "De onde vem a maioria das epistaxes e qual é a primeira conduta?", "verso": "Da região anterior do septo (plexo de Kiesselbach). Compressão das asas do nariz por 10 a 15 minutos, com a cabeça inclinada para a frente.", "fonte": "AAO-HNS, diretriz de epistaxe, 2020", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-183", "assuntoId": "ass-orl-fratura", "frente": "Quais são os sinais da fratura em blow-out da órbita?", "verso": "Diplopia ao olhar para cima por aprisionamento do reto inferior, enoftalmo e dormência na região infraorbitária. Tomografia de órbitas; aprisionamento muscular é indicação cirúrgica.", "fonte": "Revisões de trauma de face; ATLS", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-184", "assuntoId": "ass-orl-vertigem", "frente": "Quais são os quatro elementos da doença de Ménière?", "verso": "Crises de vertigem de 20 minutos a horas, perda auditiva neurossensorial flutuante, zumbido e sensação de ouvido tampado no mesmo lado.", "fonte": "Critérios da Bárány Society, 2015", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-185", "assuntoId": "ass-orl-vertigem", "frente": "Qual é o canal semicircular mais acometido na VPPB e como é o nistagmo?", "verso": "O canal posterior. Na manobra de Dix-Hallpike, o nistagmo é torcional e para cima, tem latência de alguns segundos e diminui com a repetição.", "fonte": "AAO-HNS, diretriz de VPPB, 2017", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-186", "assuntoId": "ass-orl-vertigem", "frente": "Perda auditiva neurossensorial unilateral progressiva com zumbido: o que excluir?", "verso": "Schwannoma vestibular, com ressonância de ouvidos internos com gadolínio.", "fonte": "AAO-HNS; revisões de schwannoma vestibular", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-187", "assuntoId": "ass-orl-viasaereas", "frente": "Como se decide testar ou tratar uma faringite para estreptococo?", "verso": "Pelos critérios de Centor/McIsaac: febre, exsudato amigdaliano, adenopatia cervical anterior dolorosa, ausência de tosse, ajustados pela idade. Com escore intermediário ou alto, faz-se teste rápido ou cultura antes do antibiótico.", "fonte": "IDSA, faringite, 2012", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-188", "assuntoId": "ass-orl-viasaereas", "frente": "Como se diagnostica a apneia obstrutiva do sono e qual é o tratamento no adulto e na criança?", "verso": "Polissonografia: índice de apneia-hipopneia de 5 ou mais com sintomas, ou 15 ou mais. No adulto, CPAP; na criança, a causa mais comum é hipertrofia de adenoide e amígdalas, e o tratamento é adenotonsilectomia.", "fonte": "AASM, 2017; AAP, 2012", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-189", "assuntoId": "ass-orl-viasaereas", "frente": "Como se reconhece o abscesso periamigdaliano?", "verso": "Dor de garganta intensa unilateral, trismo, voz abafada (\"batata quente\") e desvio da úvula. Tratamento: drenagem mais antibiótico.", "fonte": "ABORL-CCF; revisões de infecções cervicais", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-190", "assuntoId": "ass-alergia-anafilaxia", "frente": "Qual é o tratamento de primeira linha da anafilaxia e a dose?", "verso": "Adrenalina intramuscular na face anterolateral da coxa, 0,01 mg/kg (máximo 0,5 mg no adulto e 0,3 mg na criança), repetida a cada 5 a 15 minutos se necessário.", "fonte": "World Allergy Organization, 2020", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-191", "assuntoId": "ass-alergia-anafilaxia", "frente": "Qual é o papel do anti-histamínico e do corticoide na anafilaxia?", "verso": "São adjuvantes: aliviam prurido e urticária, mas não revertem obstrução de via aérea nem choque. Nunca substituem nem atrasam a adrenalina.", "fonte": "World Allergy Organization, 2020", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-192", "assuntoId": "ass-alergia-anafilaxia", "frente": "Por que observar o paciente após anafilaxia e o que prescrever na alta?", "verso": "Pelo risco de reação bifásica horas depois. Observação de algumas horas (mais nos casos graves) e, na alta, prescrição de adrenalina autoinjetável e encaminhamento ao alergista.", "fonte": "World Allergy Organization, 2020; ASBAI", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-193", "assuntoId": "ass-imunodeficiencias", "frente": "Quais são os sinais de alerta de imunodeficiência primária na criança?", "verso": "Duas ou mais pneumonias por ano, infecções graves ou de repetição, abscessos recorrentes, candidíase persistente, necessidade frequente de antibiótico venoso, falha de crescimento e história familiar.", "fonte": "BRAGID; Jeffrey Modell Foundation", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-194", "assuntoId": "ass-imunodeficiencias", "frente": "Qual é a imunodeficiência primária mais comum e que risco ela traz?", "verso": "A deficiência seletiva de IgA, muitas vezes assintomática. Pode causar reação grave a transfusões de hemoderivados que contêm IgA.", "fonte": "ASBAI; revisões de imunodeficiências", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-195", "assuntoId": "ass-imunodeficiencias", "frente": "Como se apresenta a agamaglobulinemia ligada ao X (Bruton)?", "verso": "Meninos com infecções bacterianas de repetição a partir dos 6 meses, quando acabam os anticorpos maternos, com linfócitos B ausentes e imunoglobulinas muito baixas. Tratamento: reposição de imunoglobulina.", "fonte": "ASBAI; ESID", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-196", "assuntoId": "ass-alergia-alimentar", "frente": "Como se conduz a alergia à proteína do leite de vaca no bebê em aleitamento materno exclusivo?", "verso": "Mantém-se o aleitamento, com a mãe fazendo dieta sem leite de vaca e derivados (e suplementando cálcio).", "fonte": "Consenso Brasileiro sobre Alergia Alimentar, SBP/ASBAI 2018", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-197", "assuntoId": "ass-alergia-alimentar", "frente": "Que fórmula se usa na APLV quando o bebê não mama no peito?", "verso": "Fórmula extensamente hidrolisada como primeira escolha; fórmula de aminoácidos nas formas graves ou sem resposta. Fórmula de soja não é indicada antes dos 6 meses, e leite de cabra não serve (reage de forma cruzada).", "fonte": "Consenso Brasileiro sobre Alergia Alimentar, 2018", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-198", "assuntoId": "ass-alergia-alimentar", "frente": "Como se diagnostica a esofagite eosinofílica?", "verso": "Disfagia ou impactação alimentar em pessoa atópica; a endoscopia com biópsia mostra 15 ou mais eosinófilos por campo de grande aumento. Tratamento com inibidor de bomba, corticoide deglutido ou dieta.", "fonte": "Consenso internacional (AGREE), 2018", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-199", "assuntoId": "ass-diverticulite", "frente": "Qual é o quadro típico da diverticulite e o exame de escolha?", "verso": "Dor em fossa ilíaca esquerda, febre e leucocitose em paciente mais velho. Tomografia de abdome com contraste confirma e mostra complicações (abscesso, perfuração).", "fonte": "ASCRS, diretriz de diverticulite, 2020", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-200", "assuntoId": "ass-diverticulite", "frente": "O que é a classificação de Hinchey?", "verso": "I: abscesso pericólico; II: abscesso pélvico ou à distância; III: peritonite purulenta; IV: peritonite fecal. Abscessos maiores são drenados por punção; III e IV exigem cirurgia (a de Hartmann é a clássica no IV).", "fonte": "ASCRS 2020; WSES 2020", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-201", "assuntoId": "ass-diverticulite", "frente": "O que fazer depois de um episódio de diverticulite?", "verso": "Colonoscopia em 6 a 8 semanas, se não houver uma recente, para excluir câncer que pode imitar diverticulite.", "fonte": "ASCRS 2020", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-202", "assuntoId": "ass-hernias", "frente": "Como se diferenciam as hérnias inguinais direta e indireta?", "verso": "A indireta passa pelo anel inguinal profundo, lateral aos vasos epigástricos inferiores (é a mais comum, inclusive em crianças). A direta sai pelo triângulo de Hesselbach, medial a esses vasos.", "fonte": "HerniaSurge, diretriz internacional, 2018", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-203", "assuntoId": "ass-hernias", "frente": "Por que a hérnia femoral é sempre operada?", "verso": "Porque tem alto risco de encarceramento e estrangulamento. Fica abaixo do ligamento inguinal e é mais comum em mulheres.", "fonte": "HerniaSurge, 2018", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-204", "assuntoId": "ass-hernias", "frente": "Como se conduz a hérnia umbilical da criança?", "verso": "A maioria fecha sozinha até os 4 ou 5 anos. Opera-se se persistir depois disso ou se houver encarceramento.", "fonte": "SBP; APSA", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-205", "assuntoId": "ass-colangite", "frente": "Quais são a tríade de Charcot e a pêntade de Reynolds?", "verso": "Charcot: febre, icterícia e dor em hipocôndrio direito. Reynolds acrescenta hipotensão e confusão mental — é colangite grave.", "fonte": "Tokyo Guidelines, 2018", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-206", "assuntoId": "ass-colangite", "frente": "Qual é o tratamento da colangite aguda?", "verso": "Antibiótico e drenagem da via biliar, de preferência por CPRE; quanto mais grave, mais urgente a drenagem.", "fonte": "Tokyo Guidelines, 2018", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-207", "assuntoId": "ass-colangite", "frente": "Quem vai direto para CPRE na suspeita de coledocolitíase?", "verso": "Quem tem alta probabilidade: cálculo visto no colédoco na imagem, colangite, ou bilirrubina acima de 4 mg/dL com colédoco dilatado. Na probabilidade intermediária, colangiorressonância ou ecoendoscopia antes.", "fonte": "ASGE, diretriz de coledocolitíase, 2019", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-208", "assuntoId": "ass-cirbariatrica", "frente": "Quem tem indicação de cirurgia bariátrica no Brasil?", "verso": "IMC de 40 ou mais, ou de 35 ou mais com comorbidade ligada à obesidade, depois de falha do tratamento clínico, em adultos com avaliação multiprofissional.", "fonte": "Conselho Federal de Medicina, Resoluções 2.131/2015 e 2.172/2017", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-209", "assuntoId": "ass-cirbariatrica", "frente": "O que pensar em dor abdominal em cólica meses após bypass gástrico?", "verso": "Hérnia interna (pelos espaços criados na reconstrução em Y de Roux), mais comum após grande perda de peso. Tomografia e, muitas vezes, laparoscopia exploradora — o risco é isquemia intestinal.", "fonte": "ASMBS; revisões de complicações bariátricas", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-210", "assuntoId": "ass-cirbariatrica", "frente": "Que deficiências nutricionais são esperadas depois do bypass gástrico?", "verso": "Ferro, vitamina B12, cálcio e vitamina D, tiamina e folato. A suplementação é por toda a vida, com exames periódicos.", "fonte": "ASMBS, diretriz de micronutrientes, 2019", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-211", "assuntoId": "ass-neo-ecn", "frente": "Qual é o quadro da enterocolite necrosante e o sinal radiológico característico?", "verso": "Prematuro com distensão abdominal, resíduo gástrico e sangue nas fezes depois de iniciada a dieta. A radiografia mostra pneumatose intestinal (e, nos graves, gás na veia porta).", "fonte": "Critérios de Bell modificados; SBP", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-212", "assuntoId": "ass-neo-ecn", "frente": "Como se trata a enterocolite necrosante e quando se opera?", "verso": "Dieta zero, sonda gástrica aberta, hidratação e antibiótico de amplo espectro. Cirurgia se houver perfuração (pneumoperitônio) ou piora apesar do tratamento.", "fonte": "SBP; revisões de ECN", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-213", "assuntoId": "ass-neo-ecn", "frente": "Qual é o principal fator de proteção contra enterocolite necrosante?", "verso": "O leite humano (da própria mãe ou de banco de leite). A progressão cuidadosa da dieta também ajuda.", "fonte": "SBP; AAP", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-214", "assuntoId": "ass-neo-prematuridade", "frente": "Quem deve fazer ultrassom transfontanelar e por quê?", "verso": "Prematuros com menos de 32 semanas, na primeira semana de vida e depois, para rastrear hemorragia peri-intraventricular, frequente e muitas vezes silenciosa.", "fonte": "SBP, Manual de Neonatologia", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-215", "assuntoId": "ass-neo-prematuridade", "frente": "Quem faz rastreamento de retinopatia da prematuridade?", "verso": "Recém-nascidos com 32 semanas ou menos, ou com 1.500 g ou menos ao nascer, com exame de fundo de olho a partir de 4 a 6 semanas de vida.", "fonte": "SBP/SBOP, diretriz de retinopatia da prematuridade", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-216", "assuntoId": "ass-neo-prematuridade", "frente": "Como se define displasia broncopulmonar?", "verso": "Necessidade de oxigênio suplementar por 28 dias ou mais, com a gravidade avaliada às 36 semanas de idade pós-menstrual.", "fonte": "Consenso do NICHD, 2001/2018", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-217", "assuntoId": "ass-neo-infeccoescongenitas", "frente": "O que se investiga no recém-nascido de mãe com sífilis não tratada ou tratada de forma inadequada?", "verso": "VDRL no sangue periférico do bebê, hemograma, líquor e radiografia de ossos longos, além de exame físico completo. O tratamento é com penicilina (cristalina ou procaína) por 10 dias, conforme a avaliação.", "fonte": "PCDT de Transmissão Vertical, Ministério da Saúde 2022", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-218", "assuntoId": "ass-neo-infeccoescongenitas", "frente": "O que é tratamento adequado da sífilis na gestante?", "verso": "Penicilina benzatina em esquema completo para a fase da doença, iniciado até 30 dias antes do parto.", "fonte": "PCDT de Transmissão Vertical, Ministério da Saúde 2022", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-219", "assuntoId": "ass-neo-infeccoescongenitas", "frente": "Como diferenciar toxoplasmose e citomegalovírus congênitos pelas calcificações?", "verso": "Toxoplasmose: calcificações difusas, com coriorretinite e hidrocefalia (tríade de Sabin). Citomegalovírus: calcificações periventriculares, microcefalia e surdez neurossensorial.", "fonte": "SBP; revisões de infecções congênitas", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-220", "assuntoId": "ass-neo-triagemneonatal", "frente": "Quando se coleta o teste do pezinho e quais doenças o programa básico cobre?", "verso": "Entre o 3º e o 5º dia de vida. Fenilcetonúria, hipotireoidismo congênito, doença falciforme e outras hemoglobinopatias, fibrose cística, hiperplasia adrenal congênita e deficiência de biotinidase.", "fonte": "Programa Nacional de Triagem Neonatal, Ministério da Saúde", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-221", "assuntoId": "ass-neo-triagemneonatal", "frente": "Por que o hipotireoidismo congênito é tratado com urgência?", "verso": "Porque a falta de hormônio tireoidiano nas primeiras semanas causa deficiência intelectual irreversível. A levotiroxina deve começar o mais cedo possível, idealmente nas duas primeiras semanas.", "fonte": "SBP; SBEM; ESPE 2020", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-222", "assuntoId": "ass-neo-triagemneonatal", "frente": "Como se faz e quando é alterado o teste do coraçãozinho?", "verso": "Oximetria no membro superior direito e num membro inferior entre 24 e 48 horas de vida. Alterado se a saturação for menor que 95% ou se a diferença entre os dois for de 3% ou mais (repete-se em 1 hora; se persistir, ecocardiograma).", "fonte": "SBP, 2011; Ministério da Saúde", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-223", "assuntoId": "ass-neo-descrresp", "frente": "Como é a taquipneia transitória do recém-nascido?", "verso": "Bebê a termo ou quase, muitas vezes nascido de cesárea sem trabalho de parto, com desconforto leve que melhora em 24 a 72 horas. Radiografia com líquido nas cissuras e congestão hilar.", "fonte": "SBP, Manual de Neonatologia", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-224", "assuntoId": "ass-neo-descrresp", "frente": "Qual é a causa e a prevenção da síndrome do desconforto respiratório do prematuro?", "verso": "Deficiência de surfactante. A radiografia mostra padrão reticulogranular (vidro moído) com broncograma aéreo. Previne-se com corticoide antenatal; trata-se com CPAP e surfactante.", "fonte": "Consenso europeu de SDR, 2022", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-225", "assuntoId": "ass-neo-descrresp", "frente": "O que caracteriza a síndrome de aspiração de mecônio?", "verso": "Recém-nascido a termo ou pós-termo com líquido meconial e desconforto respiratório; a radiografia mostra hiperinsuflação e infiltrados grosseiros. Complicação temida: hipertensão pulmonar persistente.", "fonte": "SBP, Manual de Neonatologia", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-226", "assuntoId": "ass-neo-exposicaotb", "frente": "Qual é a conduta com o recém-nascido de mãe com tuberculose pulmonar bacilífera?", "verso": "Não vacinar com BCG ao nascer. Iniciar isoniazida (ou rifampicina) e fazer prova tuberculínica aos 3 meses: se negativa, suspende-se e vacina-se com BCG; se positiva, completa-se o tratamento da infecção latente.", "fonte": "Manual de Recomendações para o Controle da Tuberculose, Ministério da Saúde 2019", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-227", "assuntoId": "ass-neo-exposicaotb", "frente": "A mãe com tuberculose pulmonar pode amamentar?", "verso": "Sim, usando máscara cirúrgica ao amamentar e ao cuidar do bebê.", "fonte": "Ministério da Saúde, 2019", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-228", "assuntoId": "ass-neo-exposicaotb", "frente": "O que excluir antes de dar isoniazida ao bebê exposto?", "verso": "Tuberculose ativa no próprio bebê (clínica e radiografia): se houver doença, o tratamento é outro, com esquema completo.", "fonte": "Ministério da Saúde, 2019", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-229", "assuntoId": "ass-neo-malformacoesdigestivas", "frente": "Como se suspeita de atresia de esôfago?", "verso": "Polidrâmnio na gestação, salivação excessiva, engasgo às mamadas e impossibilidade de passar sonda até o estômago. O tipo mais comum tem fístula traqueoesofágica distal.", "fonte": "SBP; APSA", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-230", "assuntoId": "ass-neo-malformacoesdigestivas", "frente": "O que é o sinal da dupla bolha e a que síndrome ele se associa?", "verso": "Duas bolhas de ar (estômago e duodeno) sem ar distal: atresia duodenal, frequentemente associada à síndrome de Down.", "fonte": "SBP; APSA", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-231", "assuntoId": "ass-neo-malformacoesdigestivas", "frente": "O que significa vômito bilioso no recém-nascido?", "verso": "Má rotação com volvo até prova em contrário: emergência cirúrgica, investigada com estudo contrastado do trânsito alto quando o bebê está estável.", "fonte": "APSA; AAP", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-232", "assuntoId": "ass-transmissaoverticalhiv", "frente": "Quando e como se faz a profilaxia no recém-nascido exposto ao HIV?", "verso": "O mais cedo possível, idealmente nas primeiras 4 horas de vida: zidovudina isolada nos casos de baixo risco ou esquema com três antirretrovirais nos de alto risco, conforme o protocolo vigente.", "fonte": "PCDT de Transmissão Vertical, Ministério da Saúde", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-233", "assuntoId": "ass-transmissaoverticalhiv", "frente": "A mãe que vive com HIV pode amamentar no Brasil?", "verso": "Não: a recomendação brasileira é não amamentar, inibir a lactação (cabergolina) e oferecer fórmula infantil, garantida pelo SUS.", "fonte": "PCDT de Transmissão Vertical, Ministério da Saúde", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-234", "assuntoId": "ass-transmissaoverticalhiv", "frente": "Por que não se usa sorologia para diagnosticar HIV no bebê?", "verso": "Porque os anticorpos da mãe passam pela placenta e podem persistir até 18 meses. O diagnóstico usa carga viral (RNA do HIV).", "fonte": "PCDT de Transmissão Vertical, Ministério da Saúde", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-235", "assuntoId": "ass-pneumo-bronquiectasias", "frente": "Qual é o quadro das bronquiectasias e o exame que confirma?", "verso": "Tosse crônica com muita expectoração e infecções respiratórias de repetição. Tomografia de alta resolução: brônquio mais largo que a artéria ao lado (sinal do anel de sinete) e sem afilamento para a periferia.", "fonte": "ERS, diretriz de bronquiectasias, 2017", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-236", "assuntoId": "ass-pneumo-bronquiectasias", "frente": "Quais são as causas de bronquiectasias a lembrar?", "verso": "Sequela de infecção (tuberculose, coqueluche, pneumonias), fibrose cística, discinesia ciliar primária (síndrome de Kartagener: situs inversus, sinusite e bronquiectasias), imunodeficiências e aspergilose broncopulmonar alérgica.", "fonte": "ERS 2017; BTS 2019", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-237", "assuntoId": "ass-pneumo-bronquiectasias", "frente": "Qual é a base do tratamento das bronquiectasias?", "verso": "Fisioterapia respiratória para higiene brônquica todos os dias; macrolídeo prolongado para quem exacerba com frequência; antibiótico guiado por cultura nas exacerbações.", "fonte": "ERS 2017", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-238", "assuntoId": "ass-vm", "frente": "Quais são os parâmetros da ventilação protetora na SDRA?", "verso": "Volume corrente de 6 mL/kg de peso predito, pressão de platô de até 30 cmH2O e driving pressure idealmente até 15 cmH2O; posição prona quando a relação PaO2/FiO2 está abaixo de 150.", "fonte": "ATS/ESICM/SCCM, diretriz de SDRA, 2017; AMIB", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-239", "assuntoId": "ass-vm", "frente": "Como se define e classifica a SDRA pelos critérios de Berlim?", "verso": "Início em até 1 semana, opacidades bilaterais não explicadas por insuficiência cardíaca e relação PaO2/FiO2 de até 300 com PEEP de pelo menos 5: leve (200–300), moderada (100–200) e grave (até 100).", "fonte": "Definição de Berlim, JAMA 2012", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-240", "assuntoId": "ass-vm", "frente": "O que é o teste de respiração espontânea?", "verso": "Com a causa da insuficiência respiratória controlada e o paciente estável, ele respira com suporte mínimo (pressão de suporte baixa ou tubo T) por 30 a 120 minutos; tolerando bem, é extubado.", "fonte": "Diretrizes brasileiras de ventilação mecânica, AMIB/SBPT 2013", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-241", "assuntoId": "ass-caovario", "frente": "Para que serve o CA-125?", "verso": "Principalmente para acompanhar o câncer epitelial de ovário. Na pré-menopausa é pouco específico: sobe com endometriose, miomas, gravidez e inflamação pélvica.", "fonte": "FEBRASGO; NCCN", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-242", "assuntoId": "ass-caovario", "frente": "Quais são os fatores de risco e de proteção do câncer de ovário?", "verso": "Risco: mutações BRCA1/2, síndrome de Lynch, idade, nuliparidade. Proteção: uso de anticoncepcional oral, gestações, amamentação e laqueadura/salpingectomia.", "fonte": "FEBRASGO; NCCN", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-243", "assuntoId": "ass-caovario", "frente": "Que achados de ultrassom tornam uma massa ovariana suspeita?", "verso": "Componente sólido, septos grossos, projeções papilares, vascularização ao Doppler, ascite e tamanho grande. A suspeita leva a cirurgia com estadiamento por especialista.", "fonte": "Regras simples do IOTA; O-RADS", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-244", "assuntoId": "ass-caendometrio", "frente": "Como se investiga o sangramento na pós-menopausa?", "verso": "Sempre se exclui câncer de endométrio: ultrassom transvaginal (espessura endometrial acima de 4 mm pede biópsia) e amostragem do endométrio (histeroscopia com biópsia).", "fonte": "FEBRASGO; ACOG 2018", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-245", "assuntoId": "ass-caendometrio", "frente": "Quais são os fatores de risco do câncer de endométrio?", "verso": "Estrogênio sem oposição de progesterona: obesidade, anovulação crônica (síndrome dos ovários policísticos), reposição só com estrogênio, tamoxifeno, nuliparidade e menopausa tardia; e síndrome de Lynch.", "fonte": "FEBRASGO; NCCN", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-246", "assuntoId": "ass-caendometrio", "frente": "Qual é a diferença entre os tipos I e II de câncer de endométrio?", "verso": "Tipo I: endometrioide, dependente de estrogênio, precedido por hiperplasia, bom prognóstico. Tipo II: seroso ou de células claras, em mulheres mais velhas, sem relação com estrogênio, pior prognóstico.", "fonte": "FEBRASGO; OMS", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-247", "assuntoId": "ass-doencatrofoblastica", "frente": "Como se apresenta a mola hidatiforme completa?", "verso": "Sangramento no primeiro trimestre, útero maior que a idade gestacional, beta-hCG muito alto, hiperêmese e às vezes pré-eclâmpsia precoce; ultrassom em \"flocos de neve\", sem embrião. Cariótipo 46,XX de origem paterna.", "fonte": "FEBRASGO; FIGO 2021", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-248", "assuntoId": "ass-doencatrofoblastica", "frente": "Como se trata e se acompanha a mola hidatiforme?", "verso": "Esvaziamento uterino por aspiração a vácuo e beta-hCG seriado (semanal até negativar e depois mensal), com anticoncepção durante o seguimento para não confundir com nova gestação.", "fonte": "FEBRASGO; FIGO 2021", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-249", "assuntoId": "ass-doencatrofoblastica", "frente": "O que indica neoplasia trofoblástica gestacional depois de uma mola?", "verso": "Beta-hCG que para de cair (platô) ou volta a subir. Na maioria dos casos de baixo risco, o tratamento é metotrexato, com cura muito alta.", "fonte": "Critérios da FIGO, 2000/2021", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-250", "assuntoId": "ass-cavulva", "frente": "Quem tem câncer de vulva e qual é o tipo mais comum?", "verso": "Principalmente mulheres idosas, com prurido crônico; o tipo mais comum é o carcinoma espinocelular, ligado ao HPV nas mais jovens e ao líquen escleroso nas mais velhas.", "fonte": "FEBRASGO; NCCN", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-251", "assuntoId": "ass-cavulva", "frente": "Qual é a conduta diante de uma lesão vulvar persistente?", "verso": "Biópsia: lesão vulvar que não melhora, ulcerada, pigmentada ou endurecida não pode ser tratada às cegas.", "fonte": "FEBRASGO", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-252", "assuntoId": "ass-cavulva", "frente": "Para onde drena o câncer de vulva e como se trata?", "verso": "Para os linfonodos inguinofemorais. Tratamento cirúrgico com excisão local ampla e avaliação dos linfonodos (linfonodo sentinela nos tumores pequenos).", "fonte": "NCCN; ESGO 2023", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-253", "assuntoId": "ass-uroginecologia", "frente": "Como se diferenciam incontinência de esforço e de urgência?", "verso": "Esforço: perda ao tossir, espirrar ou fazer força. Urgência (bexiga hiperativa): vontade súbita e forte, com perda antes de chegar ao banheiro. Quando há as duas, é incontinência mista.", "fonte": "ICS; FEBRASGO", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-254", "assuntoId": "ass-uroginecologia", "frente": "Qual é o primeiro tratamento da incontinência urinária de esforço?", "verso": "Treinamento supervisionado dos músculos do assoalho pélvico (fisioterapia). Sling de uretra média se não houver melhora.", "fonte": "NICE, 2019; FEBRASGO", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-255", "assuntoId": "ass-uroginecologia", "frente": "Como se trata a bexiga hiperativa?", "verso": "Primeiro medidas comportamentais (treino vesical, ajuste de líquidos e cafeína) e fisioterapia; depois antimuscarínico ou mirabegrona. Em idosas, preferir mirabegrona pela carga anticolinérgica.", "fonte": "AUA/SUFU, 2024; FEBRASGO", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-256", "assuntoId": "ass-miomatose", "frente": "Que tipo de mioma mais causa sangramento e infertilidade, e como se trata?", "verso": "O submucoso (que deforma a cavidade uterina), tratado por histeroscopia.", "fonte": "FEBRASGO; classificação FIGO de miomas", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-257", "assuntoId": "ass-miomatose", "frente": "O que é a degeneração vermelha do mioma?", "verso": "Infarto hemorrágico do mioma, típico da gestação: dor localizada e febre baixa. Tratamento conservador, com analgesia.", "fonte": "FEBRASGO", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-258", "assuntoId": "ass-miomatose", "frente": "Quais são as opções de tratamento da miomatose sintomática?", "verso": "Clínico para o sangramento (anti-inflamatório, ácido tranexâmico, progestágenos, DIU de levonorgestrel); análogo de GnRH antes da cirurgia para reduzir o mioma e corrigir anemia; miomectomia se deseja gestar; histerectomia como definitivo.", "fonte": "FEBRASGO; ACOG 2021", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-259", "assuntoId": "ass-ginecoinfantil", "frente": "Quando a puberdade é precoce e qual é o primeiro sinal na menina?", "verso": "Antes dos 8 anos na menina e dos 9 no menino. Na menina, o primeiro sinal costuma ser o broto mamário (telarca).", "fonte": "SBP; SBEM", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-260", "assuntoId": "ass-ginecoinfantil", "frente": "Qual é a causa mais comum de vulvovaginite na infância, e quando pensar em algo mais?", "verso": "A inespecífica, por higiene e proximidade anal. Corrimento persistente ou com sangue sugere corpo estranho; infecção sexualmente transmissível numa criança obriga a investigar abuso sexual.", "fonte": "FEBRASGO; SBP", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-261", "assuntoId": "ass-ginecoinfantil", "frente": "Como se define amenorreia primária?", "verso": "Ausência de menstruação aos 15 anos com caracteres sexuais secundários, ou aos 13 anos sem nenhum sinal puberal.", "fonte": "FEBRASGO; ACOG", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-262", "assuntoId": "ass-infertilidade", "frente": "Quando um casal é considerado infértil?", "verso": "Sem gestação após 12 meses de relações regulares sem contracepção, ou após 6 meses quando a mulher tem 35 anos ou mais.", "fonte": "ASRM, 2020; FEBRASGO", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-263", "assuntoId": "ass-infertilidade", "frente": "Qual é a investigação básica do casal infértil?", "verso": "Espermograma, confirmação da ovulação, avaliação da permeabilidade das tubas (histerossalpingografia) e da reserva ovariana (hormônio antimülleriano e contagem de folículos antrais).", "fonte": "ASRM; FEBRASGO", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-264", "assuntoId": "ass-infertilidade", "frente": "O que fazer com uma hidrossalpinge antes da fertilização in vitro?", "verso": "Salpingectomia (ou ligadura da tuba): o líquido da hidrossalpinge prejudica a implantação e reduz a chance de gravidez.", "fonte": "ASRM; Cochrane", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-265", "assuntoId": "ass-endometriose", "frente": "Qual é a tríade clínica da endometriose?", "verso": "Dismenorreia que piora com o tempo, dor na relação profunda (dispareunia) e infertilidade. O tratamento pode começar pelo diagnóstico clínico e de imagem, sem precisar de cirurgia para confirmar.", "fonte": "ESHRE, diretriz de endometriose, 2022", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-266", "assuntoId": "ass-endometriose", "frente": "Qual é o tratamento clínico de primeira linha da endometriose?", "verso": "Progestágenos (como dienogeste) ou anticoncepcional combinado contínuo, com analgésicos.", "fonte": "ESHRE 2022; FEBRASGO", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-267", "assuntoId": "ass-endometriose", "frente": "Como aparece o endometrioma no ultrassom?", "verso": "Cisto ovariano com conteúdo homogêneo em vidro fosco (o conteúdo \"achocolatado\").", "fonte": "IOTA; ESHRE 2022", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-268", "assuntoId": "ass-prenatal", "frente": "Como se rastreia diabetes gestacional no Brasil?", "verso": "Glicemia de jejum na primeira consulta (92 a 125 mg/dL já é diabetes gestacional; 126 ou mais, diabetes prévio). Entre 24 e 28 semanas, curva com 75 g de glicose: jejum de 92, 1 hora de 180 ou 2 horas de 153 mg/dL ou mais — um valor basta.", "fonte": "Consenso OPAS/MS/FEBRASGO/SBD, 2017", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-269", "assuntoId": "ass-prenatal", "frente": "Que exames se pedem no início do pré-natal?", "verso": "Tipagem sanguínea e fator Rh, hemograma, glicemia de jejum, testes para sífilis, HIV e hepatites B e C, sorologia para toxoplasmose, urina tipo 1 e urocultura, e ultrassonografia.", "fonte": "Ministério da Saúde, Caderno de Atenção ao Pré-natal de Baixo Risco", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-270", "assuntoId": "ass-prenatal", "frente": "Que suplementos e vacina são de rotina na gestação?", "verso": "Ácido fólico (idealmente desde antes de engravidar) e sulfato ferroso, e a vacina dTpa a partir de 20 semanas em toda gestação, para proteger o bebê contra coqueluche.", "fonte": "Ministério da Saúde; Programa Nacional de Suplementação de Ferro; PNI", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-271", "assuntoId": "ass-abortamento", "frente": "Como se classificam os abortamentos pelo colo e pelo conteúdo uterino?", "verso": "Ameaça: sangramento com colo fechado e embrião vivo. Inevitável: colo aberto. Incompleto: restos no útero. Completo: útero vazio. Retido: embrião sem batimento com colo fechado.", "fonte": "FEBRASGO; Ministério da Saúde", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-272", "assuntoId": "ass-abortamento", "frente": "Como se trata o abortamento infectado?", "verso": "Antibiótico de amplo espectro (por exemplo, clindamicina com gentamicina) e esvaziamento do útero logo após iniciar o antibiótico.", "fonte": "Ministério da Saúde, Atenção Humanizada ao Abortamento", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-273", "assuntoId": "ass-abortamento", "frente": "Qual é o método preferido para esvaziar o útero até 12 semanas?", "verso": "A aspiração manual intrauterina (AMIU), mais segura que a curetagem; o misoprostol é alternativa.", "fonte": "OMS, 2022; Ministério da Saúde", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-274", "assuntoId": "ass-aloimunizacaorh", "frente": "Como se previne a aloimunização Rh?", "verso": "Na gestante Rh negativo com Coombs indireto negativo: imunoglobulina anti-D por volta de 28 semanas (conforme o protocolo) e até 72 horas após o parto se o bebê for Rh positivo.", "fonte": "FEBRASGO; Ministério da Saúde", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-275", "assuntoId": "ass-aloimunizacaorh", "frente": "Em que outras situações a gestante Rh negativo recebe anti-D?", "verso": "Sangramento na gestação, abortamento, gravidez ectópica, mola, procedimentos invasivos (amniocentese) e trauma abdominal.", "fonte": "FEBRASGO; ACOG 2017", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-276", "assuntoId": "ass-aloimunizacaorh", "frente": "Como se acompanha a gestante já sensibilizada?", "verso": "Com Doppler da artéria cerebral média do feto: pico de velocidade sistólica acima de 1,5 múltiplo da mediana indica anemia fetal e leva a cordocentese e transfusão intrauterina.", "fonte": "SMFM, 2015; FEBRASGO", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-277", "assuntoId": "ass-gestacaomultipla", "frente": "Como se define a corionicidade dos gêmeos no ultrassom?", "verso": "No primeiro trimestre: sinal do lambda (dicoriônica) ou sinal do T (monocoriônica). É o dado que mais muda o seguimento e o risco.", "fonte": "ISUOG, diretriz de gestação gemelar, 2016/2025", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-278", "assuntoId": "ass-gestacaomultipla", "frente": "O que é a síndrome de transfusão feto-fetal?", "verso": "Complicação exclusiva das gestações monocoriônicas: um gêmeo com oligoidrâmnio (doador) e outro com polidrâmnio (receptor). O tratamento é laser por fetoscopia.", "fonte": "ISUOG 2016; SMFM", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-279", "assuntoId": "ass-gestacaomultipla", "frente": "Como se decide a via de parto nos gêmeos?", "verso": "Dicoriônicos com o primeiro gêmeo cefálico podem ter parto vaginal. Monoamnióticos nascem por cesárea, em geral entre 32 e 34 semanas.", "fonte": "ACOG; ISUOG", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-280", "assuntoId": "ass-diagnosticoprenatal", "frente": "Como se rastreiam aneuploidias no primeiro trimestre?", "verso": "Translucência nucal entre 11 e 13 semanas e 6 dias, osso nasal e bioquímica (PAPP-A e beta-hCG livre). O DNA fetal livre no sangue materno é rastreamento, não diagnóstico.", "fonte": "FMF; ISUOG; ACOG 2020", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-281", "assuntoId": "ass-diagnosticoprenatal", "frente": "Quais são os exames diagnósticos invasivos e quando se fazem?", "verso": "Biópsia de vilo corial entre 11 e 14 semanas e amniocentese a partir de 15 semanas, com pequeno risco de perda gestacional.", "fonte": "ACOG 2016; ISUOG", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-282", "assuntoId": "ass-diagnosticoprenatal", "frente": "Qual é o padrão bioquímico do primeiro trimestre na trissomia 21?", "verso": "PAPP-A baixo e beta-hCG livre alto.", "fonte": "Fetal Medicine Foundation", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-283", "assuntoId": "ass-prevencao", "frente": "Quais são os níveis de prevenção?", "verso": "Primária: promoção da saúde e proteção específica (vacina). Secundária: diagnóstico precoce e tratamento (rastreamento). Terciária: limitar sequelas e reabilitar. Quaternária: evitar intervenções desnecessárias e danos iatrogênicos.", "fonte": "Leavell & Clark; Jamoulle", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-284", "assuntoId": "ass-prevencao", "frente": "O que é o paradoxo da prevenção de Rose?", "verso": "Uma medida que traz pequeno benefício para cada pessoa, aplicada à população inteira, evita mais casos que um grande benefício a poucos de alto risco — porque a maioria dos casos vem da maioria de risco moderado.", "fonte": "Geoffrey Rose, 1985", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-285", "assuntoId": "ass-prevencao", "frente": "Quando um rastreamento se justifica?", "verso": "Quando a doença é importante, tem fase pré-clínica detectável, há teste aceitável e acurado, e tratar cedo muda o desfecho — com benefício maior que os danos (sobrediagnóstico, falsos positivos).", "fonte": "Critérios de Wilson e Jungner, OMS 1968", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-286", "assuntoId": "ass-bioestatistica", "frente": "O que são erro tipo I, erro tipo II e poder?", "verso": "Tipo I (alfa): rejeitar a hipótese nula verdadeira — um falso positivo. Tipo II (beta): não rejeitar a nula falsa — um falso negativo. Poder é 1 − beta, e cresce com o tamanho da amostra.", "fonte": "Medronho, Epidemiologia; Altman", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-287", "assuntoId": "ass-bioestatistica", "frente": "O que significa um valor de p menor que 0,05?", "verso": "Que, se a hipótese nula fosse verdadeira, a chance de encontrar um resultado tão ou mais extremo seria menor que 5%. Não é a probabilidade de a hipótese nula ser verdadeira nem mede o tamanho do efeito.", "fonte": "ASA, declaração sobre valores de p, 2016", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-288", "assuntoId": "ass-bioestatistica", "frente": "Como se lê um intervalo de confiança de 95% de risco relativo ou odds ratio?", "verso": "Se inclui 1, a associação não é estatisticamente significativa. Para diferença de médias ou de riscos, o valor neutro é 0.", "fonte": "Medronho, Epidemiologia; Altman", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-289", "assuntoId": "ass-bioestatistica", "frente": "Que teste se usa para comparar proporções e para comparar médias?", "verso": "Proporções (variáveis categóricas): qui-quadrado (ou Fisher com amostras pequenas). Médias de dois grupos: t de Student; três ou mais grupos: ANOVA. Sem distribuição normal: testes não paramétricos (Mann-Whitney, Kruskal-Wallis).", "fonte": "Medronho, Epidemiologia; Altman", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-290", "assuntoId": "ass-vigilanciasanitaria", "frente": "Qual é a diferença entre vigilância sanitária e vigilância epidemiológica?", "verso": "A sanitária controla riscos de produtos e serviços (alimentos, medicamentos, estabelecimentos). A epidemiológica acompanha doenças e agravos na população para orientar ações.", "fonte": "Lei 8.080/1990; Lei 9.782/1999", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-291", "assuntoId": "ass-vigilanciasanitaria", "frente": "Dê exemplos de doenças de notificação imediata (em até 24 horas).", "verso": "Sarampo, raiva humana, cólera, botulismo, febre amarela e paralisia flácida aguda (poliomielite), entre outras da lista nacional.", "fonte": "Lista Nacional de Notificação Compulsória, Ministério da Saúde", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-292", "assuntoId": "ass-vigilanciasanitaria", "frente": "É preciso confirmar o diagnóstico para notificar?", "verso": "Não: a suspeita já obriga a notificar. A notificação é dever de todo profissional de saúde, e não só do médico.", "fonte": "Lei 6.259/1975; Portaria de Consolidação nº 4/2017", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-293", "assuntoId": "ass-cuidadospaliativos", "frente": "Qual é o tratamento de escolha da dispneia em cuidados paliativos?", "verso": "Opioide (morfina em dose baixa), que alivia a sensação de falta de ar; oxigênio só se houver hipoxemia. Ventilador ou leque direcionado ao rosto também ajuda.", "fonte": "ANCP, Manual de Cuidados Paliativos; ASCO 2021", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-294", "assuntoId": "ass-cuidadospaliativos", "frente": "Qual é a diferença entre ortotanásia e eutanásia no Brasil?", "verso": "Ortotanásia — não prolongar artificialmente o processo de morte, mantendo conforto — é permitida. Eutanásia é crime. O paciente pode registrar diretivas antecipadas de vontade.", "fonte": "CFM, Resoluções 1.805/2006 e 1.995/2012", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-295", "assuntoId": "ass-cuidadospaliativos", "frente": "Como se conduzem as secreções ruidosas nos últimos dias de vida?", "verso": "Posicionamento, redução de líquidos e, se necessário, anticolinérgico (escopolamina). Explica-se à família que o ruído não indica sofrimento do paciente.", "fonte": "ANCP, Manual de Cuidados Paliativos", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-296", "assuntoId": "ass-comunicacaoclinica", "frente": "Quais são os passos do protocolo SPIKES para más notícias?", "verso": "Setting (ambiente), Perception (o que o paciente já sabe), Invitation (quanto quer saber), Knowledge (informar em linguagem simples), Emotions (acolher as emoções) e Strategy/Summary (plano e resumo).", "fonte": "Baile et al., 2000", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-297", "assuntoId": "ass-comunicacaoclinica", "frente": "O que propõe o método clínico centrado na pessoa?", "verso": "Explorar a doença e a experiência da pessoa com ela (sentimentos, ideias, efeitos na vida e expectativas), entender a pessoa por inteiro, construir um plano comum e fortalecer a relação médico-paciente.", "fonte": "Stewart et al., Medicina Centrada na Pessoa", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-298", "assuntoId": "ass-comunicacaoclinica", "frente": "O adolescente tem direito a consulta sozinho e a sigilo?", "verso": "Sim. O sigilo só é quebrado quando há risco à vida do próprio adolescente ou de terceiros, e ele deve ser avisado.", "fonte": "Código de Ética Médica, art. 74; ECA; SBP", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-299", "assuntoId": "ass-emergped-maustratos", "frente": "Que achados sugerem maus-tratos físicos na criança?", "verso": "Lesões em estágios diferentes de cicatrização, em áreas protegidas (costas, nádegas, orelhas), com marca de objeto, fraturas de arcos costais posteriores e fraturas metafisárias em canto, e história que não combina com a lesão ou com o desenvolvimento da criança.", "fonte": "SBP, Manual de atendimento às crianças vítimas de violência", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-300", "assuntoId": "ass-emergped-maustratos", "frente": "O que é a síndrome do bebê sacudido?", "verso": "Lactente com hematoma subdural e hemorragias retinianas, às vezes com fraturas, sem história de trauma compatível.", "fonte": "AAP, trauma craniano abusivo, 2020", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-301", "assuntoId": "ass-emergped-maustratos", "frente": "Qual é a obrigação do médico diante de suspeita de maus-tratos infantis?", "verso": "Notificar (SINAN) e comunicar ao Conselho Tutelar, além de proteger a criança — inclusive internando, se houver risco. A suspeita basta.", "fonte": "ECA, arts. 13 e 245", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-302", "assuntoId": "ass-emergped-respiratoria", "frente": "Qual é a causa mais comum de parada cardiorrespiratória na criança e a relação compressão-ventilação?", "verso": "Hipóxia por insuficiência respiratória, e não arritmia. A relação é 30:2 com um socorrista e 15:2 com dois.", "fonte": "AHA, suporte avançado de vida em pediatria, 2020", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-303", "assuntoId": "ass-emergped-respiratoria", "frente": "Como se trata o crupe viral?", "verso": "Dexametasona para todos (inclusive os leves); adrenalina nebulizada se houver estridor em repouso ou desconforto moderado a grave.", "fonte": "SBP; revisões Cochrane de crupe", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-304", "assuntoId": "ass-emergped-respiratoria", "frente": "O que fazer na suspeita de epiglotite?", "verso": "Criança toxemiada, com febre alta, salivação e em posição de tripé: não examinar a garganta nem agitar a criança; garantir a via aérea em ambiente controlado com equipe experiente.", "fonte": "SBP; AHA PALS", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-305", "assuntoId": "ass-oncopediatrica", "frente": "Como se apresenta o tumor de Wilms?", "verso": "Massa abdominal lisa que não cruza a linha média, em criança de 2 a 5 anos em bom estado geral, às vezes com hipertensão e hematúria.", "fonte": "SOBOPE; COG", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-306", "assuntoId": "ass-oncopediatrica", "frente": "O que diferencia o neuroblastoma do tumor de Wilms?", "verso": "Neuroblastoma: massa irregular que cruza a linha média, com calcificações, criança geralmente menor de 5 anos e mais doente, catecolaminas urinárias elevadas; pode dar equimose periorbitária (\"olhos de guaxinim\") e opsoclonus-mioclonus.", "fonte": "SOBOPE; COG", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-307", "assuntoId": "ass-oncopediatrica", "frente": "Qual é o sinal do retinoblastoma e como se rastreia?", "verso": "Leucocoria (reflexo branco na pupila), às vezes com estrabismo. Rastreia-se com o teste do reflexo vermelho (teste do olhinho) desde o nascimento.", "fonte": "SBP; SOBOPE", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-308", "assuntoId": "ass-cironco-melanoma", "frente": "Qual é o principal fator prognóstico do melanoma localizado?", "verso": "A espessura de Breslow (profundidade do tumor em milímetros); a ulceração também piora o prognóstico.", "fonte": "AJCC, 8ª edição", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-309", "assuntoId": "ass-cironco-melanoma", "frente": "Como se faz a biópsia de uma lesão suspeita de melanoma?", "verso": "Biópsia excisional com margem pequena (1 a 3 mm), para medir o Breslow. Nunca por raspagem (shaving). A ampliação de margem e o linfonodo sentinela vêm depois, conforme o Breslow.", "fonte": "NCCN; Sociedade Brasileira de Cirurgia Oncológica", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-310", "assuntoId": "ass-cironco-melanoma", "frente": "O que é o sinal de Hutchinson?", "verso": "Pigmentação que se estende da faixa escura da unha para a dobra ao redor: sugere melanoma subungueal (acral lentiginoso, o tipo mais comum em pele negra).", "fonte": "SBD; NCCN", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-311", "assuntoId": "ass-gastro-constipacao", "frente": "Quais são os critérios de Roma IV para constipação funcional?", "verso": "Dois ou mais entre: esforço, fezes endurecidas, sensação de evacuação incompleta ou de bloqueio, manobras manuais (em mais de 25% das evacuações) e menos de 3 evacuações por semana, por 3 meses, com início há pelo menos 6 meses.", "fonte": "Critérios de Roma IV, 2016", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-312", "assuntoId": "ass-gastro-constipacao", "frente": "Que sinais de alarme na constipação pedem colonoscopia?", "verso": "Início após os 50 anos, sangramento, perda de peso, anemia ferropriva, mudança recente do hábito intestinal e história familiar de câncer colorretal.", "fonte": "AGA, 2013; Roma IV", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-313", "assuntoId": "ass-gastro-constipacao", "frente": "Como se trata a constipação funcional da criança?", "verso": "Desimpactação quando há fecaloma e manutenção com polietilenoglicol (primeira linha), além de treino de toalete e orientação alimentar.", "fonte": "ESPGHAN/NASPGHAN, 2014", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-314", "assuntoId": "ass-hepatopatiasautoimunes", "frente": "Qual é o perfil da colangite biliar primária?", "verso": "Mulher de meia-idade com prurido e fadiga, fosfatase alcalina elevada e anticorpo antimitocôndria positivo. Tratamento com ácido ursodesoxicólico.", "fonte": "EASL, diretriz de CBP, 2017", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-315", "assuntoId": "ass-hepatopatiasautoimunes", "frente": "A que doença se associa a colangite esclerosante primária e como é a imagem?", "verso": "À retocolite ulcerativa. A colangiorressonância mostra estenoses e dilatações alternadas nos ductos biliares (\"contas de rosário\"); há risco de colangiocarcinoma.", "fonte": "EASL, diretriz de CEP, 2022", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-316", "assuntoId": "ass-hepatopatiasautoimunes", "frente": "Como se reconhece e se trata a hepatite autoimune?", "verso": "Mulher com hepatite, IgG elevada e autoanticorpos (FAN e antimúsculo liso no tipo 1; anti-LKM1 no tipo 2, mais em crianças). Tratamento com corticoide e azatioprina.", "fonte": "EASL, diretriz de hepatite autoimune, 2015", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-317", "assuntoId": "ass-dii", "frente": "Como diferenciar doença de Crohn e retocolite ulcerativa?", "verso": "Crohn: qualquer segmento da boca ao ânus (principalmente íleo terminal), transmural, lesões salteadas, fístulas, granulomas, poupa o reto. Retocolite: só mucosa, contínua a partir do reto, sangramento predominante.", "fonte": "ECCO, 2019; GEDIIB", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-318", "assuntoId": "ass-dii", "frente": "O que é megacólon tóxico?", "verso": "Complicação grave da colite (principalmente retocolite): cólon dilatado acima de 6 cm com toxemia. Tratamento clínico intensivo e colectomia se não houver melhora rápida.", "fonte": "ECCO; ACG 2019", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-319", "assuntoId": "ass-dii", "frente": "Como o tabagismo influencia as doenças inflamatórias intestinais?", "verso": "Piora a doença de Crohn e parece proteger contra a retocolite ulcerativa — o que nunca justifica fumar.", "fonte": "ECCO; GEDIIB", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-320", "assuntoId": "ass-deficvitaminica", "frente": "Quais são as manifestações da deficiência de tiamina (B1)?", "verso": "Beribéri seco (neuropatia periférica), beribéri úmido (insuficiência cardíaca de alto débito) e encefalopatia de Wernicke (confusão, ataxia, oftalmoplegia), sobretudo em alcoolistas e desnutridos.", "fonte": "Revisões de deficiências vitamínicas", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-321", "assuntoId": "ass-deficvitaminica", "frente": "O que é a pelagra?", "verso": "Deficiência de niacina (B3): dermatite em áreas expostas ao sol, diarreia e demência — os três Ds —, que pode levar à morte.", "fonte": "Revisões de deficiências vitamínicas", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-322", "assuntoId": "ass-deficvitaminica", "frente": "Quais são os sinais da deficiência de vitamina A?", "verso": "Cegueira noturna, xeroftalmia e manchas de Bitot na conjuntiva, além de mais gravidade em infecções como o sarampo. No Brasil, há suplementação para crianças de 6 a 59 meses nas áreas de risco.", "fonte": "Programa Nacional de Suplementação de Vitamina A, Ministério da Saúde", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-323", "assuntoId": "ass-intolerancialactose", "frente": "Qual é a diferença entre intolerância à lactose e alergia à proteína do leite?", "verso": "A intolerância é falta da enzima lactase: gases, distensão e diarreia depois de laticínios, sem reação imunológica. A alergia é reação do sistema imune às proteínas do leite e pode ser grave.", "fonte": "WGO; Consenso Brasileiro de Alergia Alimentar", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-324", "assuntoId": "ass-intolerancialactose", "frente": "Como se confirma a intolerância à lactose?", "verso": "Teste do hidrogênio expirado ou teste de tolerância à lactose — ou melhora clara com a redução da lactose.", "fonte": "WGO; revisões de má absorção", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-325", "assuntoId": "ass-intolerancialactose", "frente": "É preciso tirar toda a lactose da dieta?", "verso": "Não: reduz-se até o nível tolerado, podendo usar lactase em cápsulas, cuidando do cálcio. A intolerância que aparece após diarreia aguda é transitória.", "fonte": "WGO; SBP", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-326", "assuntoId": "ass-nefro-glomerulopatias", "frente": "O que define síndrome nefrótica e qual é a causa mais comum na criança?", "verso": "Proteinúria nefrótica (acima de 3,5 g/dia no adulto; na criança, acima de 50 mg/kg/dia), hipoalbuminemia, edema e dislipidemia. Na criança, a lesão mínima, que costuma responder ao corticoide.", "fonte": "KDIGO, glomerulopatias, 2021", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-327", "assuntoId": "ass-nefro-glomerulopatias", "frente": "Como é a glomerulonefrite pós-estreptocócica?", "verso": "Hematúria, edema e hipertensão 1 a 3 semanas após faringite (ou 3 a 6 após impetigo), com complemento C3 baixo que se normaliza em até 8 semanas. Tratamento de suporte.", "fonte": "KDIGO 2021; SBP", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-328", "assuntoId": "ass-nefro-glomerulopatias", "frente": "Qual é a glomerulonefrite primária mais comum e como ela se apresenta?", "verso": "Nefropatia por IgA: hematúria macroscópica 1 a 3 dias depois de infecção das vias aéreas (\"sinfaringítica\"), diferente da pós-estreptocócica, que demora semanas.", "fonte": "KDIGO 2021", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-329", "assuntoId": "ass-infecto-covid", "frente": "Quem se beneficia de dexametasona na covid-19?", "verso": "Pacientes hospitalizados que precisam de oxigênio ou de ventilação mecânica: reduz mortalidade. Em quem não precisa de oxigênio não há benefício e pode haver dano.", "fonte": "Estudo RECOVERY, 2020; OMS", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-330", "assuntoId": "ass-infecto-covid", "frente": "Para quem e até quando se indica nirmatrelvir com ritonavir?", "verso": "Pacientes com covid-19 leve a moderada e alto risco de agravar, não hospitalizados, iniciando até 5 dias do início dos sintomas. Atenção às interações medicamentosas causadas pelo ritonavir.", "fonte": "OMS; Ministério da Saúde", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-331", "assuntoId": "ass-infecto-covid", "frente": "Por que se usa anticoagulação no paciente internado com covid-19?", "verso": "Porque a doença aumenta muito o risco de tromboembolismo venoso: todo internado sem contraindicação recebe profilaxia com heparina.", "fonte": "OMS; ASH 2022", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-332", "assuntoId": "ass-hanseniase", "frente": "Quais são os sinais que definem caso de hanseníase?", "verso": "Lesão de pele com alteração de sensibilidade, espessamento de nervo periférico com alteração sensitiva ou motora, ou baciloscopia positiva — basta um.", "fonte": "Ministério da Saúde, Protocolo de hanseníase, 2022", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-333", "assuntoId": "ass-hanseniase", "frente": "Como se classifica e se trata a hanseníase?", "verso": "Paucibacilar: até 5 lesões e baciloscopia negativa; multibacilar: mais de 5 lesões ou baciloscopia positiva. Poliquimioterapia única (rifampicina, dapsona e clofazimina): 6 doses no paucibacilar e 12 no multibacilar.", "fonte": "PCDT de Hanseníase, Ministério da Saúde 2022", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-334", "assuntoId": "ass-hanseniase", "frente": "Como se tratam as reações hansênicas?", "verso": "Tipo 1 (reversa, com piora das lesões e neurite): prednisona. Tipo 2 (eritema nodoso hansênico, com nódulos dolorosos e febre): talidomida — proibida para mulheres que podem engravidar sem contracepção segura — ou corticoide. A poliquimioterapia não é suspensa.", "fonte": "PCDT de Hanseníase, Ministério da Saúde 2022", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-335", "assuntoId": "ass-saudepopulacoes", "frente": "Como se organiza a atenção à saúde indígena no SUS?", "verso": "Por um subsistema próprio, com 34 Distritos Sanitários Especiais Indígenas (DSEI), coordenado pela Secretaria de Saúde Indígena (SESAI) do Ministério da Saúde.", "fonte": "Política Nacional de Atenção à Saúde dos Povos Indígenas; Lei 9.836/1999", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-336", "assuntoId": "ass-saudepopulacoes", "frente": "Pessoa em situação de rua precisa de comprovante de endereço para ser atendida no SUS?", "verso": "Não. Além do atendimento em qualquer unidade, existem as equipes de Consultório na Rua, que vão até a população.", "fonte": "Política Nacional para a População em Situação de Rua; Portaria 940/2011", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-337", "assuntoId": "ass-saudepopulacoes", "frente": "O que reconhece a Política Nacional de Saúde Integral da População Negra?", "verso": "O racismo como determinante social de saúde, com atenção a condições mais frequentes ou mais graves nessa população, como doença falciforme, hipertensão e mortalidade materna.", "fonte": "Portaria GM/MS 992/2009", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-338", "assuntoId": "ass-saudetrabalhador", "frente": "O que fazer diante de um acidente de trabalho?", "verso": "Emitir a Comunicação de Acidente de Trabalho (CAT) — qualquer médico pode, inclusive do SUS — e notificar no SINAN quando for agravo de notificação.", "fonte": "Lei 8.213/1991; Ministério da Saúde", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-339", "assuntoId": "ass-saudetrabalhador", "frente": "Como é a audiometria da perda auditiva induzida por ruído?", "verso": "Perda neurossensorial bilateral e simétrica, com entalhe em 3, 4 ou 6 kHz e recuperação em 8 kHz. É irreversível: o que se faz é prevenir e afastar do ruído.", "fonte": "Ministério da Saúde, PAIR; ACOEM", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-340", "assuntoId": "ass-saudetrabalhador", "frente": "Como se estabelece que uma doença é relacionada ao trabalho?", "verso": "Pela anamnese ocupacional (o que faz, como, há quanto tempo, a que se expõe) e pelo nexo entre exposição e doença. Os CEREST, da RENAST, apoiam a rede.", "fonte": "Ministério da Saúde, Doenças Relacionadas ao Trabalho", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-341", "assuntoId": "ass-tabagismo", "frente": "Como é a abordagem breve do fumante?", "verso": "Perguntar sobre o tabagismo, avaliar a disposição para parar, aconselhar a parar, preparar (data, estratégias, medicação) e acompanhar — os \"5 As\".", "fonte": "INCA; PCDT do Tabagismo, Ministério da Saúde", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-342", "assuntoId": "ass-tabagismo", "frente": "Quais medicamentos o SUS oferece para parar de fumar e qual é a contraindicação importante?", "verso": "Terapia de reposição de nicotina (adesivo mais goma ou pastilha) e bupropiona. A bupropiona é contraindicada em epilepsia e em transtornos alimentares (bulimia, anorexia).", "fonte": "PCDT do Tabagismo, Ministério da Saúde 2020", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-343", "assuntoId": "ass-tabagismo", "frente": "O que avalia o teste de Fagerström?", "verso": "O grau de dependência de nicotina. Fumar o primeiro cigarro nos primeiros 5 minutos após acordar é um dos sinais de dependência alta.", "fonte": "INCA; Fagerström, 1991", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-344", "assuntoId": "ass-assistenciasocial", "frente": "Quem tem direito ao Benefício de Prestação Continuada (BPC/LOAS)?", "verso": "Idoso a partir de 65 anos ou pessoa com deficiência, com renda familiar por pessoa de até 1/4 do salário-mínimo. É assistência social: não exige contribuição ao INSS.", "fonte": "Lei Orgânica da Assistência Social, Lei 8.742/1993", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-345", "assuntoId": "ass-assistenciasocial", "frente": "Quem tem direito ao auxílio por incapacidade temporária (antigo auxílio-doença)?", "verso": "O segurado do INSS incapaz de trabalhar por mais de 15 dias seguidos, em geral com 12 contribuições de carência (dispensada em acidentes e em doenças graves listadas em lei).", "fonte": "Lei 8.213/1991", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-346", "assuntoId": "ass-assistenciasocial", "frente": "O atestado médico pode trazer o CID?", "verso": "Só com autorização do paciente (ou por dever legal). O atestado deve descrever a incapacidade e o tempo de afastamento.", "fonte": "CFM, Resolução 1.658/2002; Código de Ética Médica", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-347", "assuntoId": "ass-farmacovigilancia", "frente": "Que receita exige cada grupo de medicamentos controlados?", "verso": "Opioides e anfetamínicos: notificação de receita A (amarela). Benzodiazepínicos: notificação B (azul). Antidepressivos, anticonvulsivantes e antipsicóticos: receita de controle especial (branca, em duas vias).", "fonte": "Portaria SVS/MS 344/1998", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-348", "assuntoId": "ass-farmacovigilancia", "frente": "Como é a receita de antibiótico?", "verso": "Em duas vias, uma retida na farmácia, com validade de 10 dias a partir da emissão.", "fonte": "ANVISA, RDC 20/2011 (atualizada pela RDC 471/2021)", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-349", "assuntoId": "ass-farmacovigilancia", "frente": "O que se faz com a suspeita de reação adversa a medicamento?", "verso": "Notificar à ANVISA (sistema VigiMed) — é a base da farmacovigilância, que detecta problemas que os estudos antes do registro não mostraram.", "fonte": "ANVISA, farmacovigilância", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-350", "assuntoId": "ass-gestaosaude", "frente": "O que são as Organizações Sociais de Saúde?", "verso": "Entidades privadas sem fins lucrativos que gerenciam serviços públicos de saúde por meio de contrato de gestão com o poder público. O serviço continua público, gratuito e do SUS.", "fonte": "Lei 9.637/1998", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-351", "assuntoId": "ass-gestaosaude", "frente": "O que um contrato de gestão define?", "verso": "Metas quantitativas e qualitativas, indicadores, forma de acompanhamento e repasse de recursos ligado ao desempenho, sob fiscalização do poder público e controle social.", "fonte": "Lei 9.637/1998", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-352", "assuntoId": "ass-gestaosaude", "frente": "Quais são os princípios doutrinários e organizativos do SUS?", "verso": "Doutrinários: universalidade, integralidade e equidade. Organizativos: descentralização, regionalização e hierarquização, e participação da comunidade.", "fonte": "Constituição Federal, art. 198; Leis 8.080/1990 e 8.142/1990", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-353", "assuntoId": "ass-infectoped-pneumonia", "frente": "Quais são os valores de taquipneia da OMS na criança?", "verso": "60 ou mais por minuto abaixo de 2 meses; 50 ou mais de 2 a 11 meses; 40 ou mais de 1 a 4 anos. É o sinal clínico isolado mais útil para pneumonia.", "fonte": "OMS, AIDPI", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-354", "assuntoId": "ass-infectoped-pneumonia", "frente": "Como se trata a pneumonia bacteriana típica da criança sem sinais de gravidade?", "verso": "Em casa, com amoxicilina oral. Tiragem subcostal importante, hipoxemia, incapacidade de beber, convulsão, letargia ou idade abaixo de 2 meses indicam internação.", "fonte": "SBP; OMS 2014", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-355", "assuntoId": "ass-infectoped-pneumonia", "frente": "Qual é o agente mais comum e qual complicação lembra estafilococo?", "verso": "O pneumococo é o mais comum. Pneumatoceles e derrame pleural de evolução rápida lembram Staphylococcus aureus.", "fonte": "SBP; revisões de pneumonia pediátrica", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-356", "assuntoId": "ass-bronquiolite", "frente": "O que é bronquiolite viral aguda?", "verso": "Primeiro episódio de sibilância em criança menor de 2 anos, após pródromo de resfriado, causado principalmente pelo vírus sincicial respiratório. O diagnóstico é clínico.", "fonte": "AAP, diretriz de bronquiolite, 2014; SBP", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-357", "assuntoId": "ass-bronquiolite", "frente": "O que funciona e o que não funciona no tratamento da bronquiolite?", "verso": "Funciona: suporte — hidratação, aspiração nasal, oxigênio se a saturação estiver baixa. Não se recomendam de rotina broncodilatador, corticoide ou fisioterapia respiratória.", "fonte": "AAP 2014; SBP", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-358", "assuntoId": "ass-bronquiolite", "frente": "Como se previne a bronquiolite grave nos bebês de risco?", "verso": "Com anticorpo monoclonal contra o vírus sincicial respiratório (palivizumabe, e nirsevimabe onde disponível) para prematuros de risco, cardiopatas e crianças com doença pulmonar crônica, conforme critérios do Ministério da Saúde.", "fonte": "Ministério da Saúde; SBP", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-359", "assuntoId": "ass-oft-tumores", "frente": "Qual é o tumor intraocular primário mais comum do adulto e para onde ele se espalha?", "verso": "Melanoma de coroide: massa pigmentada que pode ter forma de cogumelo ao romper a membrana de Bruch. Dá metástase preferencialmente para o fígado.", "fonte": "COMS; Sociedade Brasileira de Oncologia Oftalmológica", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-360", "assuntoId": "ass-oft-tumores", "frente": "Qual é o tumor intraocular mais comum na infância?", "verso": "Retinoblastoma, que se apresenta com leucocoria e estrabismo. Na forma hereditária (bilateral, gene RB1), há risco de outros tumores, como osteossarcoma.", "fonte": "SOBOPE; AAO", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-361", "assuntoId": "ass-oft-tumores", "frente": "Considerando todos os tumores dentro do olho do adulto, qual é o mais frequente?", "verso": "As metástases (principalmente de mama e pulmão), mais que qualquer tumor primário.", "fonte": "AAO, Basic and Clinical Science Course", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-362", "assuntoId": "ass-crescimentopuberdade", "frente": "Quando a baixa estatura merece investigação?", "verso": "Estatura abaixo de −2 desvios-padrão (ou do percentil 3) para idade e sexo, ou — mais importante — velocidade de crescimento baixa, que cruza percentis para baixo.", "fonte": "SBP; SBEM", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-363", "assuntoId": "ass-crescimentopuberdade", "frente": "Como diferenciar baixa estatura familiar de atraso constitucional?", "verso": "Familiar: pais baixos, idade óssea igual à cronológica, puberdade na época certa. Constitucional: idade óssea atrasada, puberdade tardia e altura final normal — muitas vezes com história parecida em um dos pais.", "fonte": "SBP; SBEM", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-364", "assuntoId": "ass-crescimentopuberdade", "frente": "Quando a puberdade é considerada atrasada?", "verso": "Menina sem broto mamário aos 13 anos; menino sem aumento testicular (volume de 4 mL) aos 14 anos.", "fonte": "SBP; SBEM", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-365", "assuntoId": "ass-acessovenoso", "frente": "Qual local de cateter venoso central tem menor risco de infecção, e como se punciona?", "verso": "Subclávia tem o menor risco de infecção; femoral, o maior (e mais trombose). A punção guiada por ultrassom (sobretudo na jugular interna) reduz complicações.", "fonte": "CDC, prevenção de infecção de cateter, 2011", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-366", "assuntoId": "ass-acessovenoso", "frente": "O que se faz depois de passar um cateter em jugular ou subclávia?", "verso": "Radiografia de tórax: confirma a ponta na junção da veia cava superior com o átrio direito e exclui pneumotórax.", "fonte": "Diretrizes de acesso venoso central", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-367", "assuntoId": "ass-acessovenoso", "frente": "Como se diagnostica infecção de corrente sanguínea relacionada a cateter e quando retirar o cateter?", "verso": "Hemoculturas pareadas (do cateter e periférica): a do cateter positivando 2 horas ou mais antes sugere o cateter como origem. Retira-se o cateter em infecção por Staphylococcus aureus, Pseudomonas, fungos e em sepse grave.", "fonte": "IDSA, infecção de cateter, 2009", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-368", "assuntoId": "ass-paratireoide", "frente": "Como se diagnostica hiperparatireoidismo primário?", "verso": "Cálcio alto com PTH alto ou inapropriadamente normal. A causa mais comum é um adenoma único. Clássico: cálculos, dor óssea, sintomas abdominais e alterações psíquicas.", "fonte": "Workshop internacional de hiperparatireoidismo, 2022", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-369", "assuntoId": "ass-paratireoide", "frente": "Como se trata a hipercalcemia grave?", "verso": "Hidratação venosa com soro fisiológico, depois bisfosfonato (zoledronato); calcitonina tem efeito rápido, mas curto.", "fonte": "Endocrine Society, hipercalcemia de malignidade, 2023", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-370", "assuntoId": "ass-paratireoide", "frente": "Como se reconhece e se trata a hipocalcemia depois de tireoidectomia?", "verso": "Formigamento perioral e nos dedos, sinais de Chvostek e Trousseau, câimbras. Se sintomática, gluconato de cálcio venoso; depois cálcio e calcitriol por via oral.", "fonte": "ATA; SBEM", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-371", "assuntoId": "ass-hipofise", "frente": "Qual é o adenoma hipofisário funcionante mais comum e o tratamento?", "verso": "Prolactinoma: galactorreia, irregularidade menstrual e infertilidade (no homem, queda de libido). Tratamento com agonista dopaminérgico (cabergolina), mesmo em macroadenoma.", "fonte": "Endocrine Society, 2011; SBEM", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-372", "assuntoId": "ass-hipofise", "frente": "O que é apoplexia hipofisária e qual é a conduta imediata?", "verso": "Hemorragia ou infarto de um adenoma: cefaleia súbita intensa, alteração visual ou paralisia ocular e insuficiência hipofisária aguda. Hidrocortisona venosa imediatamente e avaliação neurocirúrgica.", "fonte": "Society for Endocrinology, 2011", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-373", "assuntoId": "ass-hipofise", "frente": "O que é a síndrome de Sheehan?", "verso": "Necrose da hipófise após hemorragia intensa no parto: a mulher não consegue amamentar (agalactia) e não volta a menstruar.", "fonte": "Revisões de hipopituitarismo; SBEM", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},

  {"id": "fc-n-374", "assuntoId": "ass-traumatorax", "frente": "Quando suspeitar de lesão de aorta torácica no trauma?", "verso": "Em desaceleração brusca (queda de altura, colisão frontal). A radiografia pode mostrar mediastino alargado; a angiotomografia confirma. Controla-se frequência e pressão até o tratamento, em geral endovascular.", "fonte": "ATLS, 10ª edição", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-375", "assuntoId": "ass-traumatorax", "frente": "O que é tórax instável e qual é o verdadeiro problema?", "verso": "Duas ou mais costelas vizinhas fraturadas em dois ou mais pontos, com movimento paradoxal do segmento. O que mais pesa é a contusão pulmonar embaixo; trata-se com analgesia eficaz e ventilação quando necessária.", "fonte": "ATLS, 10ª edição", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
  {"id": "fc-n-376", "assuntoId": "ass-traumatorax", "frente": "Quando o hemotórax traumático vai para toracotomia?", "verso": "Drenagem inicial de 1.500 mL ou mais, saída acima de 200 mL por hora durante 2 a 4 horas, ou instabilidade que não responde.", "fonte": "ATLS, 10ª edição", "revisao": "pendente", "criadoPor": "seed", "criadoEm": "2026-09-24"},
]);
